  tan: new THREE.MeshStandardMaterial({ color: 0x8a7550, roughness: 0.75, metalness: 0.12 }),
  accent: new THREE.MeshStandardMaterial({ color: 0xff7a00, roughness: 0.35, metalness: 0.55, emissive: 0x3a1400, emissiveIntensity: 0.8 }),
  glove: new THREE.MeshStandardMaterial({ color: 0x1f2426, roughness: 0.85 }),
  glovePad: new THREE.MeshStandardMaterial({ color: 0x333a3b, roughness: 0.7 }),
  sleeve: new THREE.MeshStandardMaterial({ color: 0x3c4334, roughness: 0.95 }),
  skin: new THREE.MeshStandardMaterial({ color: 0x8a5c3f, roughness: 0.85 }),
  glass: new THREE.MeshStandardMaterial({ color: 0x6fd6c4, roughness: 0.08, metalness: 0.2, transparent: true, opacity: 0.35 }),
  dot: new THREE.MeshBasicMaterial({ color: 0xff3b20 }),
  brass: new THREE.MeshStandardMaterial({ color: 0xc79a4a, roughness: 0.35, metalness: 0.8 })
};

function box(w, h, d, mat, x = 0, y = 0, z = 0) {
  const m = new THREE.Mesh(new THREE.BoxGeometry(w, h, d), mat);
  m.position.set(x, y, z);
  return m;
}
function cyl(rTop, rBot, h, mat, seg = 12) {
  return new THREE.Mesh(new THREE.CylinderGeometry(rTop, rBot, h, seg), mat);
}
function addRail(parent, y, z, len, mat = M.gun) {
  for (let i = 0; i < Math.floor(len / 0.025); i++) {
    parent.add(box(0.055, 0.008, 0.014, mat, 0, y, z - len / 2 + i * 0.025 + 0.01));
  }
}

function buildHands(group) {
  // right hand on the grip
  const rArm = new THREE.Group();
  const rPalm = box(0.075, 0.1, 0.13, M.glove, 0, 0, 0);
  rArm.add(rPalm);
  const rKnuckle = box(0.078, 0.035, 0.1, M.glovePad, 0, 0.045, -0.005);
  rArm.add(rKnuckle);
  for (let i = 0; i < 4; i++) {
    const f = box(0.018, 0.03, 0.07, M.glove, -0.028 + i * 0.019, 0.005, -0.095);
    f.rotation.x = -0.45;
    rArm.add(f);
  }
  const thumb = box(0.025, 0.06, 0.03, M.glove, 0.042, 0.02, -0.045);
  thumb.rotation.z = 0.35; rArm.add(thumb);
  const rForearm = new THREE.Mesh(new THREE.CapsuleGeometry(0.052, 0.24, 4, 8), M.sleeve);
  rForearm.rotation.x = Math.PI / 2.55;
  rForearm.position.set(0.018, -0.055, 0.2);
  rArm.add(rForearm);
  const cuff = new THREE.Mesh(new THREE.CylinderGeometry(0.062, 0.058, 0.06, 10), M.tan);
  cuff.rotation.x = Math.PI / 2; cuff.position.set(0.018, -0.04, 0.11); rArm.add(cuff);
  rArm.position.set(0.015, -0.115, 0.09);
  rArm.rotation.set(0.25, 0, -0.08);
  group.add(rArm);

  // left hand on the handguard
  const lArm = new THREE.Group();
  const lPalm = box(0.08, 0.07, 0.15, M.glove, 0, 0, 0);
  lArm.add(lPalm);
  const lPad = box(0.082, 0.03, 0.11, M.glovePad, 0, 0.04, 0);
  lArm.add(lPad);
  for (let i = 0; i < 4; i++) {
    const f = box(0.019, 0.032, 0.075, M.glove, -0.028 + i * 0.019, -0.038, 0.01);
    f.rotation.x = 0.4;
    lArm.add(f);
  }
  const thumb = box(0.026, 0.05, 0.07, M.glove, 0.044, -0.02, 0.02);
  thumb.rotation.z = -0.4; lArm.add(thumb);
  const lForearm = new THREE.Mesh(new THREE.CapsuleGeometry(0.05, 0.28, 4, 8), M.sleeve);
  lForearm.rotation.x = Math.PI / 2.3;
  lForearm.position.set(-0.04, -0.055, 0.2);
  lArm.add(lForearm);
  const lCuff = new THREE.Mesh(new THREE.CylinderGeometry(0.06, 0.055, 0.06, 10), M.tan);
  lCuff.rotation.x = Math.PI / 2; lCuff.position.set(-0.035, -0.04, 0.11); lArm.add(lCuff);
  return { right: rArm, left: lArm };
}

function baseRifle() {
  const g = new THREE.Group();

  const receiver = box(0.088, 0.105, 0.4, M.gun, 0, 0, -0.04);
  g.add(receiver);
  // upper receiver + rail
  g.add(box(0.07, 0.036, 0.42, M.gunLight, 0, 0.068, -0.06));
  addRail(g, 0.09, -0.06, 0.36);
  // handguard
  const hg = box(0.077, 0.082, 0.34, M.tan, 0, 0.005, -0.41);
  g.add(hg);
  for (let i = 0; i < 5; i++) {
    const slot = box(0.079, 0.016, 0.032, M.gun, 0, -0.012, -0.3 - i * 0.055);
    g.add(slot);
  }
  // barrel + brake
  const barrel = cyl(0.016, 0.018, 0.32, M.gunLight, 10);
  barrel.rotation.x = Math.PI / 2; barrel.position.set(0, 0.012, -0.71); g.add(barrel);
  const brake = cyl(0.029, 0.026, 0.085, M.gun, 10);
  brake.rotation.x = Math.PI / 2; brake.position.set(0, 0.012, -0.885); g.add(brake);
  for (let i = 0; i < 3; i++) {
    const port = box(0.02, 0.008, 0.04, M.accent, i % 2 ? 0.021 : -0.021, 0.012, -0.875);
    g.add(port);
  }
  // stock
  g.add(box(0.07, 0.1, 0.2, M.polymer, 0, -0.005, 0.25));
  g.add(box(0.062, 0.15, 0.055, M.polymer, 0, -0.03, 0.345));
  g.add(box(0.074, 0.05, 0.08, M.gun, 0, 0.055, 0.23));
  // grip
  const grip = box(0.058, 0.13, 0.075, M.polymer, 0, -0.105, 0.075);
  grip.rotation.x = -0.24; g.add(grip);
  // trigger guard
  const guard = new THREE.Mesh(new THREE.TorusGeometry(0.038, 0.008, 4, 10, Math.PI), M.gun);
  guard.rotation.set(Math.PI / 2, 0, 0); guard.position.set(0, -0.08, 0.005); g.add(guard);
  // magazine
  const magGroup = new THREE.Group();
  const mag = box(0.066, 0.19, 0.11, M.polymer, 0, -0.09, 0);
  mag.rotation.x = 0.14;
  magGroup.add(mag);
  magGroup.add(box(0.07, 0.02, 0.115, M.gun, 0, -0.185, 0.012));
  magGroup.position.set(0, -0.085, -0.04);
  g.add(magGroup);
  // charging handle / bolt
  g.add(box(0.055, 0.02, 0.03, M.gunLight, 0, 0.075, 0.06));
  // optic
  const optic = new THREE.Group();
  const base = box(0.058, 0.028, 0.15, M.gun, 0, 0, 0); optic.add(base);
  const tube = new THREE.Mesh(new THREE.CylinderGeometry(0.043, 0.043, 0.14, 14), M.gun);
  tube.rotation.x = Math.PI / 2; tube.position.set(0, 0.045, 0); optic.add(tube);
  for (const zz of [-0.07, 0.07]) {
    const ring = new THREE.Mesh(new THREE.TorusGeometry(0.044, 0.008, 5, 14), M.gunLight);
    ring.position.set(0, 0.045, zz); optic.add(ring);
  }
  const lens = new THREE.Mesh(new THREE.CircleGeometry(0.038, 16), M.glass);
  lens.position.set(0, 0.045, -0.071); optic.add(lens);
  const dot = new THREE.Mesh(new THREE.SphereGeometry(0.0045, 6, 5), M.dot);
  dot.position.set(0, 0.045, -0.072); optic.add(dot);
  optic.position.set(0, 0.095, -0.08);
  g.add(optic);
  // side accents
  g.add(box(0.004, 0.035, 0.16, M.accent, 0.046, 0.015, -0.02));
  g.add(box(0.004, 0.025, 0.12, M.accent, -0.046, 0.015, -0.3));
  g.add(box(0.045, 0.012, 0.045, M.accent, 0, 0.058, 0.12));
  // laser / flashlight
  const laser = cyl(0.014, 0.014, 0.09, M.gunLight, 8);
  laser.rotation.x = Math.PI / 2; laser.position.set(-0.048, -0.005, -0.52); g.add(laser);
  const laserGlass = new THREE.Mesh(new THREE.CircleGeometry(0.012, 8), M.glass);
  laserGlass.position.set(-0.048, -0.005, -0.565); g.add(laserGlass);

  const muzzle = new THREE.Object3D();
  muzzle.position.set(0, 0.012, -0.93);
  g.add(muzzle);

  const hands = buildHands(g);
  hands.left.position.set(-0.005, -0.02, -0.43);
  hands.left.rotation.set(0.1, 0, 0.12);
  g.add(hands.left);

  g.userData = { magGroup, muzzle, optic, type: 'rifle', sightY: 0.14, sightZ: -0.08 };
  return g;
}

function buildSMG() {
  const g = new THREE.Group();
  g.add(box(0.09, 0.11, 0.3, M.gun, 0, 0, 0));
  g.add(box(0.068, 0.034, 0.34, M.gunLight, 0, 0.072, -0.03));
  g.add(box(0.08, 0.075, 0.2, M.polymer, 0, -0.01, -0.26));
  for (let i = 0; i < 4; i++) {
    g.add(box(0.082, 0.012, 0.026, M.accent, 0, -0.005, -0.19 - i * 0.043));
  }
  const barrel = cyl(0.02, 0.022, 0.18, M.gunLight, 10);
  barrel.rotation.x = Math.PI / 2; barrel.position.set(0, 0.012, -0.41); g.add(barrel);
  const suppressor = cyl(0.034, 0.034, 0.19, M.gun, 12);
  suppressor.rotation.x = Math.PI / 2; suppressor.position.set(0, 0.012, -0.55); g.add(suppressor);
  for (let i = 0; i < 4; i++) g.add(box(0.07, 0.008, 0.012, M.gunLight, 0, 0.028, -0.49 - i * 0.04));
  // stock
  g.add(box(0.05, 0.06, 0.22, M.gunLight, 0, 0.005, 0.25));
  g.add(box(0.075, 0.13, 0.05, M.polymer, 0, -0.02, 0.36));
  // grip + curved mag
  const grip = box(0.055, 0.12, 0.07, M.polymer, 0, -0.1, 0.07);
  grip.rotation.x = -0.22; g.add(grip);
  const magGroup = new THREE.Group();
  const mag1 = box(0.058, 0.16, 0.085, M.polymer, 0, -0.06, 0);
  mag1.rotation.x = 0.18; magGroup.add(mag1);
  const mag2 = box(0.056, 0.13, 0.08, M.polymer, 0, -0.17, 0.035);
  mag2.rotation.x = 0.38; magGroup.add(mag2);
  magGroup.position.set(0, -0.09, -0.02);
  g.add(magGroup);
  // optic — small reflex sight
  const optic = new THREE.Group();
  optic.add(box(0.055, 0.02, 0.11, M.gun, 0, 0, 0));
  const hood = box(0.05, 0.055, 0.045, M.gunLight, 0, 0.038, 0.045);
  optic.add(hood);
  const glass = new THREE.Mesh(new THREE.PlaneGeometry(0.042, 0.045), M.glass);
  glass.position.set(0, 0.045, 0.018); optic.add(glass);
  const dot = new THREE.Mesh(new THREE.SphereGeometry(0.0038, 6, 5), M.dot);
  dot.position.set(0, 0.045, 0.015); optic.add(dot);
  optic.position.set(0, 0.095, -0.07);
  g.add(optic);
  g.add(box(0.004, 0.03, 0.2, M.accent, 0.047, 0.01, -0.12));
  // hands
  const hands = buildHands(g);
  hands.left.position.set(0, -0.02, -0.28);
  hands.left.rotation.set(0.15, 0, 0.12);
  g.add(hands.left);

  const muzzle = new THREE.Object3D();
  muzzle.position.set(0, 0.012, -0.64);
  g.add(muzzle);
  g.userData = { magGroup, muzzle, optic, type: 'smg', sightY: 0.14, sightZ: -0.07 };
  return g;
}

export function buildWeapon(type) {
  return type === 'smg' ? buildSMG() : baseRifle();
}

export function createMuzzleFlash() {
  const tex = radialTexture(128, 'rgba(255,255,235,1)', 'rgba(255,190,80,0.7)', 'rgba(255,120,20,0)');
  const mat = new THREE.SpriteMaterial({
    map: tex, color: 0xffd8a0, transparent: true, blending: THREE.AdditiveBlending,
    depthWrite: false, depthTest: false
  });
  const sprite = new THREE.Sprite(mat);
  sprite.scale.setScalar(0.34);
  sprite.visible = false;
  const light = new THREE.PointLight(0xffa64d, 0, 6, 2);
  return { sprite, light, timer: 0 };
}

import * as THREE from 'three';
import { radialTexture } from './utils.js';

function decalTexture() {
  const c = document.createElement('canvas'); c.width = c.height = 64;
  const ctx = c.getContext('2d');
  ctx.clearRect(0, 0, 64, 64);
  const g = ctx.createRadialGradient(32, 32, 0, 32, 32, 20);
  g.addColorStop(0, 'rgba(8,7,6,0.95)');
  g.addColorStop(0.5, 'rgba(14,12,10,0.75)');
  g.addColorStop(1, 'rgba(20,18,15,0)');
  ctx.fillStyle = g; ctx.beginPath(); ctx.arc(32, 32, 21, 0, Math.PI * 2); ctx.fill();
  ctx.strokeStyle = 'rgba(10,9,8,0.6)'; ctx.lineWidth = 1.4;
  for (let i = 0; i < 7; i++) {
    const a = Math.random() * Math.PI * 2, l = 4 + Math.random() * 13;
    ctx.beginPath(); ctx.moveTo(32, 32); ctx.lineTo(32 + Math.cos(a) * l, 32 + Math.sin(a) * l); ctx.stroke();
  }
  const t = new THREE.CanvasTexture(c); t.colorSpace = THREE.SRGBColorSpace; return t;
}

export class Effects {
  constructor(scene) {
    this.scene = scene;
    this.particles = [];
    this.tracers = [];
    this.decals = [];
    this.shells = [];
    this.pool = [];
    this.maxParticles = 120;

    this.smokeTex = radialTexture(96, 'rgba(255,240,220,0.9)', 'rgba(210,190,160,0.4)', 'rgba(190,170,140,0)');
    this.sparkTex = radialTexture(64, 'rgba(255,255,240,1)', 'rgba(255,190,90,0.8)', 'rgba(255,120,20,0)');
    this.bloodTex = radialTexture(64, 'rgba(255,90,70,1)', 'rgba(160,20,10,0.65)', 'rgba(90,0,0,0)');
    this.decalTex = decalTexture();

    for (let i = 0; i < this.maxParticles; i++) {
      const s = new THREE.Sprite(new THREE.SpriteMaterial({
        map: this.smokeTex, transparent: true, depthWrite: false,
        blending: THREE.NormalBlending, opacity: 0
      }));
      s.visible = false;
      scene.add(s);
      this.pool.push(s);
    }
  }

  _getSprite(map, blending = THREE NormalBlending) {
    let s = this.pool.find(p => !p.visible);
    if (!s) {
      s = this.pool.reduce((a, b) => (a.material.opacity <= b.material.opacity ? a : b));
    }
    s.visible = true;
    s.material.map = map;
    s.material.blending = blending;
    s.material.opacity = 1;
    s.material.rotation = 0;
    return s;
  }

  particle(pos, vel, { map = this.smokeTex, color = 0xffffff, size = 0.3, life = 0.5, gravity = 0, drag = 1, fade = 1, blending = THREE.NormalBlending, grow = 0, spin = 0 } = {}) {
    const s = this._getSprite(map, blending);
    s.position.copy(pos);
    s.material.color.setHex(color);
    s.material.opacity = 1;
    s.scale.setScalar(size);
    s.visible = true;
    this.particles.push({
      sprite: s, vel: vel.clone(), life, maxLife: life, gravity, drag, fade, grow, spin
    });
  }

  muzzleSmoke(pos, dir) {
    for (let i = 0; i < 2; i++) {
      const v = dir.clone().multiplyScalar(0.6 + Math.random() * 1.2);
      v.x += (Math.random() - 0.5) * 0.4; v.y += 0.25 + Math.random() * 0.4; v.z += (Math.random() - 0.5) * 0.4;
      this.particle(pos, v, { size: 0.16 + Math.random() * 0.12, life: 0.35 + Math.random() * 0.3, gravity: 0.7, drag: 0.1, grow: 0.9, color: 0xd8d2c6 });
    }
  }

  impact(point, normal, kind = 'world') {
    // sparks
    for (let i = 0; i < 5; i++) {
      const v = normal.clone().multiplyScalar(1.5 + Math.random() * 2.5);
      v.x += (Math.random() - 0.5) * 2.4; v.y += (Math.random() - 0.5) * 2.4 + 0.6; v.z += (Math.random() - 0.5) * 2.4;
      this.particle(point, v, { map: this.sparkTex, color: 0xffc06a, size: 0.055 + Math.random() * 0.04, life: 0.25 + Math.random() * 0.3, gravity: 7, drag: 0.4, blending: THREE.AdditiveBlending });
    }
    // dust puff
    for (let i = 0; i < 2; i++) {
      const v = normal.clone().multiplyScalar(0.7);
      v.x += (Math.random() - 0.5) * 0.8; v.y += 0.3 + Math.random() * 0.4; v.z += (Math.random() - 0.5) * 0.8;
      this.particle(point, v, { map: this.smokeTex, color: kind === 'metal' ? 0xb9b3a6 : 0xcfc3a8, size: 0.16, life: 0.45, gravity: 0.5, drag: 0.2, grow: 0.7 });
    }
    // bullet hole
    if (this.decals.length > 55) {
      const old = this.decals.shift();
      this.scene.remove(old.mesh);
      old.mesh.geometry.dispose();
      old.mesh.material.dispose();
    }
    const m = new THREE.Mesh(new THREE.PlaneGeometry(0.15, 0.15), new THREE.MeshBasicMaterial({
      map: this.decalTex, transparent: true, depthWrite: false, polygonOffset: true, polygonOffsetFactor: -4, opacity: 0.9
    }));
    m.position.copy(point).addScaledVector(normal, 0.006);
    m.lookAt(point.clone().add(normal));
    m.rotateZ(Math.random() * Math.PI);
    this.scene.add(m);
    this.decals.push({ mesh: m, life: 26 });
  }

  blood(point, dir) {
    for (let i = 0; i < 7; i++) {
      const v = dir.clone().multiplyScalar(1.2 + Math.random() * 1.8);
      v.x += (Math.random() - 0.5) * 2.2; v.y += (Math.random() - 0.5) * 1.8 + 0.5; v.z += (Math.random() - 0.5) * 2.2;
      this.particle(point, v, { map: this.bloodTex, color: 0xb01d12, size: 0.08 + Math.random() * 0.09, life: 0.35 + Math.random() * 0.25, gravity: 6, drag: 0.6 });
    }
    this.particle(point, dir.clone().multiplyScalar(0.5), { map: this.bloodTex, color: 0x7a0d08, size: 0.24, life: 0.35, grow: 1.4, gravity: 0.6 });
  }

  tracer(from, to, color = 0xffd08a) {
    const geo = new THREE.BufferGeometry().setFromPoints([from, to]);
    const mat = new THREE.LineBasicMaterial({ color, transparent: true, opacity: 0.9, blending: THREE.AdditiveBlending, depthWrite: false });
    const line = new THREE.Line(geo, mat);
    this.scene.add(line);
    this.tracers.push({ line, life: 0.075, maxLife: 0.075 });
  }

  shell(pos, vel) {
    if (this.shells.length > 24) {
      const old = this.shells.shift();
      this.scene.remove(old.mesh);
      old.mesh.geometry.dispose();
      old.mesh.material.dispose();
    }
    const mesh = new THREE.Mesh(new THREE.CylinderGeometry(0.012, 0.012, 0.045, 6), new THREE.MeshStandardMaterial({ color: 0xc9a052, metalness: 0.8, roughness: 0.35 }));
    mesh.position.copy(pos);
    mesh.rotation.set(Math.random() * 3, Math.random() * 3, Math.random() * 3);
    this.scene.add(mesh);
    this.shells.push({ mesh, vel: vel.clone(), life: 2.4, spin: new THREE.Vector3(Math.random() * 8, Math.random() * 8, Math.random() * 8) });
  }

  update(dt) {
    for (let i = this.particles.length - 1; i >= 0; i--) {
      const p = this.particles[i];
      p.life -= dt;
      if (p.life <= 0) {
        p.sprite.visible = false;
        p.sprite.material.opacity = 0;
        this.particles.splice(i, 1);
        continue;
      }
      p.vel.y -= p.gravity * dt;
      p.vel.multiplyScalar(1 - Math.min(0.95, p.drag * dt * 3));
      p.sprite.position.addScaledVector(p.vel, dt);
      const t = p.life / p.maxLife;
      p.sprite.material.opacity = Math.pow(t, p.fade);
      if (p.grow) p.sprite.scale.setScalar(p.sprite.scale.x + p.grow * dt);
      if (p.spin) p.sprite.material.rotation += p.spin * dt;
    }
    for (let i = this.tracers.length - 1; i >= 0; i--) {
      const tr = this.tracers[i];
      tr.life -= dt;
      tr.line.material.opacity = Math.max(0, tr.life / tr.maxLife) * 0.9;
      if (tr.life <= 0) {
        this.scene.remove(tr.line);
        tr.line.geometry.dispose();
        tr.line.material.dispose();
        this.tracers.splice(i, 1);
      }
    }
    for (let i = this.decals.length - 1; i >= 0; i--) {
      const d = this.decals[i];
      d.life -= dt;
      if (d.life < 3) d.mesh.material.opacity = Math.max(0, d.life / 3) * 0.9;
      if (d.life <= 0) {
        this.scene.remove(d.mesh);
        d.mesh.geometry.dispose();
        d.mesh.material.dispose();
        this.decals.splice(i, 1);
      }
    }
    for (let i = this.shells.length - 1; i >= 0; i--) {
      const s = this.shells[i];
      s.life -= dt;
      s.vel.y -= 9.8 * dt;
      s.mesh.position.addScaledVector(s.vel, dt);
      s.mesh.rotation.x += s.spin.x * dt;
      s.mesh.rotation.y += s.spin.y * dt;
      if (s.mesh.position.y < 0.02) { s.mesh.position.y = 0.02; s.vel.y *= -0.35; s.vel.x *= 0.7; s.vel.z *= 0.7; }
      if (s.life <= 0) {
        this.scene.remove(s.mesh);
        s.mesh.geometry.dispose();
        s.mesh.material.dispose();
        this.shells.splice(i, 1);
      }
    }
  }
}

