import * as THREE from 'three';
import { clamp, damp, randRange, mulberry32, lerp } from './utils.js';
import { radialTexture } from './utils.js';

const BOT_NAMES = [
  'FANTASMA', 'CACIQUE', 'TIGRE', 'CORVO', 'LOBO', 'SOMBRA', 'REI', 'VULCÃO',
  'TEMPESTADE', 'JAGUAR', 'FALCÃO', 'BRUXO', 'METEORO', 'TITÃ', 'ORION', 'SERPENTE'
];

const skinTones = [0x8a5c3f, 0x6d452c, 0xa9744f, 0x513322];
const shirtColors = [0x4a5138, 0x3d4433, 0x585440, 0x343d34, 0x5b4b36];
const helmetColors = [0x2b2e2a, 0x3b3d32, 0x262a26];

function glowSprite() {
  return radialTexture(64, 'rgba(255,240,200,1)', 'rgba(255,180,70,0.85)', 'rgba(255,120,20,0)');
}

export class EnemyManager {
  constructor(scene, world, effects, audio) {
    this.scene = scene;
    this.world = world;
    this.effects = effects;
    this.audio = audio;
    this.rng = mulberry32(9911);
    this.enemies = [];
    this.hitMeshes = [];
    this.flashTex = glowSprite();
    this.total = 0;
    this.onKill = null;

    this._v1 = new THREE.Vector3();
    this._v2 = new THREE.Vector3();
    this._v3 = new THREE.Vector3();
  }

  spawn(count, player) {
    const points = [...this.world.spawnPoints];
    // Sort so bots start spread around the player, not on top of them.
    let pi = 0;
    for (let i = 0; i < count; i++) {
      let pt = points[pi % points.length];
      pi++;
      for (let tries = 0; tries < 12; tries++) {
        const cand = points[Math.floor(this.rng() * points.length)];
        const d = Math.hypot(cand.x - player.position.x, cand.z - player.position.z);
        if (d > 32) { pt = cand; break; }
      }
      const e = new Enemy(this, pt.x + randRange(this.rng, -6, 6), pt.z + randRange(this.rng, -6, 6), i);
      this.enemies.push(e);
      this.scene.add(e.group);
      this.hitMeshes.push(...e.hitMeshes);
    }
    this.total = count;
  }

  get alive() {
    return this.enemies.filter(e => !e.dead).length;
  }

  update(dt, player, time) {
    for (const e of this.enemies) e.update(dt, player, time);
  }

  raycast(raycaster) {
    const hits = raycaster.intersectObjects(this.hitMeshes, false);
    for (const h of hits) {
      const owner = h.object.userData.enemy;
      if (owner && !owner.dead) return h;
    }
    return null;
  }

  reset() {
    for (const e of this.enemies) {
      this.scene.remove(e.group);
      e.dispose();
    }
    this.enemies.length = 0;
    this.hitMeshes.length = 0;
  }
}

class Enemy {
  constructor(manager, x, z, index) {
    this.manager = manager;
    this.world = manager.world;
    this.effects = manager.effects;
    this.audio = manager.audio;
    this.rng = mulberry32(5000 + index * 7717);
    this.name = BOT_NAMES[index % BOT_NAMES.length];
    this.maxHp = 100;
    this.hp = 100;
    this.armor = index % 3 === 0 ? 20 : 0;
    this.dead = false;
    this.deathT = 0;
    this.speed = 2.5 + this.rng() * 0.7;
    this.range = 24 + this.rng() * 16;
    this.fireTimer = 1 + this.rng() * 2;
    this.burst = 0;
    this.burstTimer = 0;
    this.reloadTimer = 0;
    this.shotsInMag = 18 + Math.floor(this.rng() * 10);
    this.strafe = this.rng() > 0.5 ? 1 : -1;
    this.strafeTimer = 1 + this.rng() * 2;
    this.state = 'patrol';
    this.target = new THREE.Vector3(x, 0, z);
    this.lastSeen = new THREE.Vector3(x, 0, z);
    this.losTimer = this.rng() * 0.3;
    this.hasLos = false;
    this.walkPhase = this.rng() * 6;
    this.flashTimer = 0;
    this.aimPitch = 0;
    this.hitMeshes = [];
    this.disposed = false;

    this.group = new THREE.Group();
    this.group.position.set(x, this.world.heightAt(x, z), z);
    this.group.rotation.y = this.rng() * Math.PI * 2;
    this._build();
  }

  _build() {
    const rng = this.rng;
    const skin = new THREE.MeshStandardMaterial({ color: skinTones[Math.floor(rng() * skinTones.length)], roughness: 0.75 });
    const shirt = new THREE.MeshStandardMaterial({ color: shirtColors[Math.floor(rng() * shirtColors.length)], roughness: 0.9 });
    const pants = new THREE.MeshStandardMaterial({ color: 0x31362e, roughness: 0.95 });
    const vest = new THREE.MeshStandardMaterial({ color: 0x22261f, roughness: 0.82 });
    const helmetMat = new THREE.MeshStandardMaterial({ color: helmetColors[Math.floor(rng() * helmetColors.length)], roughness: 0.65, metalness: 0.1 });
    const accent = new THREE.MeshStandardMaterial({ color: 0xff6a1a, roughness: 0.5, emissive: 0x4a1600, emissiveIntensity: 0.8 });
    const gunMat = new THREE.MeshStandardMaterial({ color: 0x191b1d, roughness: 0.5, metalness: 0.7 });

    const root = new THREE.Group();
    this.bodyRoot = root;
    this.group.add(root);

    // legs
    this.legL = new THREE.Group();
    this.legR = new THREE.Group();
    for (const [leg, sx] of [[this.legL, -1], [this.legR, 1]]) {
      const thigh = new THREE.Mesh(new THREE.CapsuleGeometry(0.095, 0.36, 3, 7), pants);
      thigh.position.y = -0.23; leg.add(thigh);
      const shin = new THREE.Mesh(new THREE.CapsuleGeometry(0.08, 0.34, 3, 7), pants);
      shin.position.y = -0.66; leg.add(shin);
      const boot = new THREE.Mesh(new THREE.BoxGeometry(0.14, 0.12, 0.28), vest);
      boot.position.set(0, -0.87, 0.05); leg.add(boot);
      leg.position.set(sx * 0.12, 0.9, 0);
      root.add(leg);
    }

    // torso
    const torso = new THREE.Mesh(new THREE.CapsuleGeometry(0.21, 0.34, 4, 9), shirt);
    torso.position.y = 1.22;
    torso.scale.set(1.08, 1, 0.72);
    root.add(torso);
    const vestMesh = new THREE.Mesh(new THREE.BoxGeometry(0.42, 0.42, 0.28), vest);
    vestMesh.position.set(0, 1.24, 0.01);
    root.add(vestMesh);
    for (let i = 0; i < 3; i++) {
      const pouch = new THREE.Mesh(new THREE.BoxGeometry(0.1, 0.11, 0.07), vest);
      pouch.position.set(-0.13 + i * 0.13, 1.09, 0.17);
      root.add(pouch);
    }
    const belt = new THREE.Mesh(new THREE.BoxGeometry(0.38, 0.07, 0.26), vest);
    belt.position.y = 0.98; root.add(belt);
    const shoulder = new THREE.Mesh(new THREE.BoxGeometry(0.12, 0.1, 0.2), accent);
    shoulder.position.set(0.25, 1.4, 0); root.add(shoulder);

    // arms
    this.armL = new THREE.Group();
    this.armR = new THREE.Group();
    for (const [arm, sx] of [[this.armL, -1], [this.armR, 1]]) {
      const upper = new THREE.Mesh(new THREE.CapsuleGeometry(0.07, 0.26, 3, 6), shirt);
      upper.position.y = -0.16; arm.add(upper);
      const fore = new THREE.Mesh(new THREE.CapsuleGeometry(0.06, 0.24, 3, 6), skin);
      fore.position.y = -0.44; arm.add(fore);
      const glove = new THREE.Mesh(new THREE.BoxGeometry(0.1, 0.12, 0.11), vest);
      glove.position.y = -0.6; arm.add(glove);
      arm.position.set(sx * 0.29, 1.38, 0);
      root.add(arm);
    }

    // head
    this.head = new THREE.Group();
    const skull = new THREE.Mesh(new THREE.SphereGeometry(0.135, 12, 10), skin);
    skull.scale.set(0.95, 1.05, 1);
    this.head.add(skull);
    const helmet = new THREE.Mesh(new THREE.SphereGeometry(0.155, 12, 8, 0, Math.PI * 2, 0, Math.PI * 0.55), helmetMat);
    helmet.position.y = 0.035;
    this.head.add(helmet);
    const brim = new THREE.Mesh(new THREE.BoxGeometry(0.19, 0.025, 0.13), helmetMat);
    brim.position.set(0, 0.04, 0.11); this.head.add(brim);
    const goggles = new THREE.Mesh(new THREE.BoxGeometry(0.17, 0.045, 0.03), new THREE.MeshStandardMaterial({ color: 0x101514, roughness: 0.3, metalness: 0.3 }));
    goggles.position.set(0, 0.01, 0.12); this.head.add(goggles);
    this.head.position.y = 1.58;
    root.add(this.head);

    // rifle
    this.gun = new THREE.Group();
    const gbody = new THREE.Mesh(new THREE.BoxGeometry(0.06, 0.09, 0.42), gunMat);
    this.gun.add(gbody);
    const gbarrel = new THREE.Mesh(new THREE.CylinderGeometry(0.014, 0.014, 0.36, 7), gunMat);
    gbarrel.rotation.x = Math.PI / 2; gbarrel.position.set(0, 0.01, -0.34); this.gun.add(gbarrel);
    const gmag = new THREE.Mesh(new THREE.BoxGeometry(0.05, 0.14, 0.06), gunMat);
    gmag.position.set(0, -0.1, -0.02); gmag.rotation.x = 0.18; this.gun.add(gmag);
    const gstock = new THREE.Mesh(new THREE.BoxGeometry(0.05, 0.08, 0.16), gunMat);
    gstock.position.set(0, -0.005, 0.26); this.gun.add(gstock);
    const sight = new THREE.Mesh(new THREE.BoxGeometry(0.03, 0.03, 0.08), accent);
    sight.position.set(0, 0.06, -0.05); this.gun.add(sight);
    this.gun.position.set(0.16, 1.24, 0.12);
    this.gun.rotation.y = -0.1;
    root.add(this.gun);
    this.muzzle = new THREE.Object3D();
    this.muzzle.position.set(0, 0.01, -0.54);
    this.gun.add(this.muzzle);

    // aim arms
    this.armR.rotation.set(-1.15, 0.1, 0.18);
    this.armL.rotation.set(-1.3, 0, -0.5);

    // hit boxes (invisible, reliable)
    const hitMat = new THREE.MeshBasicMaterial({ transparent: true, opacity: 0, depthWrite: false, colorWrite: false });
    const bodyHit = new THREE.Mesh(new THREE.BoxGeometry(0.56, 0.82, 0.4), hitMat);
    bodyHit.position.y = 1.2;
    const headHit = new THREE.Mesh(new THREE.SphereGeometry(0.19, 8, 6), hitMat);
    headHit.position.y = 1.61;
    for (const [mesh, part] of [[bodyHit, 'body'], [headHit, 'head']]) {
      mesh.userData.enemy = this;
      mesh.userData.part = part;
      root.add(mesh);
      this.hitMeshes.push(mesh);
    }

    // muzzle flash sprite
    this.flash = new THREE.Sprite(new THREE.SpriteMaterial({
      map: this.manager.flashTex, color: 0xffc27a, transparent: true, depthWrite: false,
      blending: THREE.AdditiveBlending
    }));
    this.flash.scale.setScalar(0.7);
    this.flash.visible = false;
    this.muzzle.add(this.flash);

    // health bar sprite
    this.healthCanvas = document.createElement('canvas');
    this.healthCanvas.width = 64; this.healthCanvas.height = 10;
    this.healthTex = new THREE.CanvasTexture(this.healthCanvas);
    this.healthSprite = new THREE.Sprite(new THREE.SpriteMaterial({ map: this.healthTex, transparent: true, depthWrite: false, depthTest: false }));
    this.healthSprite.scale.set(1.1, 0.14, 1);
    this.healthSprite.position.y = 2.15;
    this.healthSprite.visible = false;
    root.add(this.healthSprite);
    this._drawHealth();

    // shadow flag
    root.traverse((o) => {
      if (o.isMesh && o.material !== hitMat) { o.castShadow = true; o.receiveShadow = true; }
    });
  }

  _drawHealth() {
    const ctx = this.healthCanvas.getContext('2d');
    ctx.clearRect(0, 0, 64, 10);
    ctx.fillStyle = 'rgba(0,0,0,0.65)'; ctx.fillRect(0, 0, 64, 10);
    const pct = clamp(this.hp / this.maxHp, 0, 1);
    ctx.fillStyle = pct > 0.55 ? '#63e6a0' : pct > 0.25 ? '#ffc14d' : '#ff4f3d';
    ctx.fillRect(1, 1, 62 * pct, 8);
    this.healthTex.needsUpdate = true;
  }

  _losTo(player) {
    const p = this.group.position;
    const q = player.position;
    // terrain line of sight
    const steps = 10;
    for (let i = 1; i < steps; i++) {
      const t = i / steps;
      const x = lerp(p.x, q.x, t), z = lerp(p.z, q.z, t);
      const h = this.world.heightAt(x, z);
      const ly = lerp(p.y + 1.5, q.y + 1.4, t);
      if (h > ly + 0.15) return false;
    }
    // prop line of sight (2D circles)
    for (const c of this.world.colliders) {
      if (!c.los) continue;
      const dx = q.x - p.x, dz = q.z - p.z;
      const fx = p.x - c.x, fz = p.z - c.z;
      const a = dx * dx + dz * dz;
      if (a < 0.0001) continue;
      let t = -(fx * dx + fz * dz) / a;
      t = clamp(t, 0, 1);
      const cx = p.x + dx * t - c.x, cz = p.z + dz * t - c.z;
      if (cx * cx + cz * cz < c.r * c.r * 0.72) return false;
    }
    return true;
  }

  _move(dt, dirX, dirZ, speed) {
    const len = Math.hypot(dirX, dirZ);
    if (len < 0.001) return;
    dirX /= len; dirZ /= len;
    let nx = this.group.position.x + dirX * speed * dt;
    let nz = this.group.position.z + dirZ * speed * dt;
    if (this.world.heightAt(nx, nz) < 1.2) {
      // steer back to the island centre
      const a = Math.atan2(-this.group.position.z, -this.group.position.x);
      nx = this.group.position.x + Math.cos(a) * speed * dt;
      nz = this.group.position.z + Math.sin(a) * speed * dt;
    }
    // collision slide
    for (const c of this.world.colliders) {
      const dx = nx - c.x, dz = nz - c.z;
      const d = Math.hypot(dx, dz);
      const min = c.r + 0.35;
      if (d < min && d > 0.0001) {
        nx = c.x + (dx / d) * min;
        nz = c.z + (dz / d) * min;
      }
    }
    this.group.position.x = nx;
    this.group.position.z = nz;
    this.group.position.y = this.world.heightAt(nx, nz);
  }

  _shoot(player) {
    const dist = this.group.position.distanceTo(player.position);
    const from = this._v1;
    this.muzzle.getWorldPosition(from);
    const target = this._v2;
    target.copy(player.position);
    target.y += 1.35;
    const moving = player.isMoving;
    const difficulty = this.manager.rng;
    const acc = clamp(1 - dist / 75, 0.25, 1) * (moving ? 0.72 : 1) * 0.82;
    const hit = difficulty() < acc * 0.62;
    const spread = hit ? 0.06 : 1.1 + difficulty() * 2.2;
    target.x += (difficulty() - 0.5) * spread;
    target.y += (difficulty() - 0.5) * spread * 0.7;
    target.z += (difficulty() - 0.5) * spread;
    this.effects.tracer(from, target, 0xffb066);
    this.flash.visible = true;
    this.flash.material.rotation = difficulty() * 6;
    this.flashTimer = 0.05;
    this.audio.enemyShot(dist);
    if (hit) {
      const dmg = 7 + difficulty() * 5;
      player.damage(dmg, this.group.position.clone());
    }
  }

  hit(damage, part, point) {
    if (this.dead) return false;
    let dmg = damage;
    if (part === 'head') dmg *= 2.15;
    if (this.armor > 0) {
      const absorbed = Math.min(this.armor, dmg * 0.55);
      this.armor -= absorbed;
      dmg -= absorbed;
    }
    this.hp -= dmg;
    this.healthSprite.visible = true;
    this._drawHealth();
    this.state = 'engage';
    if (this.hp <= 0) {
      this.die();
      return true;
    }
    return false;
  }

  die() {
    this.dead = true;
    this.deathT = 0;
    this.hp = 0;
    this.healthSprite.visible = false;
    this.flash.visible = false;
    this.manager.onKill?.(this);
  }

  update(dt, player, time) {
    if (this.dead) {
      this.deathT += dt;
      const t = clamp(this.deathT / 0.65, 0, 1);
      this.bodyRoot.rotation.x = -t * Math.PI / 2;
      this.bodyRoot.position.y = t * -0.18;
      if (this.deathT > 7 && !this.disposed) {
        this.disposed = true;
        this.group.visible = false;
      }
      return;
    }

    const p = this.group.position;
    const dx = player.position.x - p.x;
    const dz = player.position.z - p.z;
    const dist = Math.hypot(dx, dz);
    this.losTimer -= dt;
    if (this.losTimer <= 0) {
      this.losTimer = 0.22 + this.rng() * 0.2;
      this.hasLos = dist < 85 && this._losTo(player);
    }

    // face player when engaged
    const targetYaw = Math.atan2(dx, dz);
    if (dist < 70 || this.state === 'engage') {
      let d = targetYaw - this.group.rotation.y;
      while (d > Math.PI) d -= Math.PI * 2;
      while (d < -Math.PI) d += Math.PI * 2;
      this.group.rotation.y += d * Math.min(1, dt * (this.state === 'engage' ? 5 : 2));
    }

    if (this.hasLos && dist < 68) {
      this.state = 'engage';
      this.lastSeen.set(player.position.x, player.position.y, player.position.z);
      // maintain combat distance and strafe
      this.strafeTimer -= dt;
      if (this.strafeTimer <= 0) {
        this.strafeTimer = 1.2 + this.rng() * 2.4;
        this.strafe *= -1;
      }
      const forward = dist > this.range + 6 ? 1 : dist < this.range - 9 ? -0.6 : 0;
      const moveX = (dx / dist) * forward + (-dz / dist) * this.strafe * 0.75;
      const moveZ = (dz / dist) * forward + (dx / dist) * this.strafe * 0.75;
      this._move(dt, moveX, moveZ, this.speed * (forward !== 0 ? 1 : 0.75));
      // aiming
      this.armR.rotation.x = damp(this.armR.rotation.x, -1.32 - clamp((player.position.y - p.y) * 0.04, -0.2, 0.3), 8, dt);
      // fire control
      this.fireTimer -= dt;
      if (this.reloadTimer > 0) {
        this.reloadTimer -= dt;
      } else if (this.burst > 0) {
        this.burstTimer -= dt;
        if (this.burstTimer <= 0) {
          this.burstTimer = 0.13;
          this.burst--;
          this.shotsInMag--;
          this._shoot(player);
          if (this.burst <= 0) this.fireTimer = 0.5 + this.rng() * 1.15;
          if (this.shotsInMag <= 0) { this.reloadTimer = 2.1; this.shotsInMag = 18 + Math.floor(this.rng() * 10); }
        }
      } else if (this.fireTimer <= 0) {
        this.burst = 2 + Math.floor(this.rng() * 4);
        this.burstTimer = 0;
      }
    } else {
      // advance toward last seen position, otherwise wander
      const goal = this.state === 'engage' ? this.lastSeen : this.target;
      const gx = goal.x - p.x, gz = goal.z - p.z;
      const gd = Math.hypot(gx, gz);
      if (gd > 2.5) {
        this._move(dt, gx, gz, this.speed * 0.92);
      } else if (this.state !== 'engage') {
        // pick a new patrol target
        const a = this.rng() * Math.PI * 2, r = 20 + this.rng() * 50;
        this.target.set(Math.cos(a) * r, 0, Math.sin(a) * r);
      }
      if (this.state === 'engage' && !this.hasLos) this.fireTimer = Math.max(this.fireTimer, 0.35);
    }

    // walk animation
    const moved = this.state !== 'engage' || dist > this.range + 6 || dist < this.range - 9;
    if (moved) {
      this.walkPhase += dt * (this.state === 'engage' ? 7 : 5.5);
      const swing = Math.sin(this.walkPhase) * 0.55;
      this.legL.rotation.x = swing;
      this.legR.rotation.x = -swing;
      if (!this.hasLos) {
        this.armL.rotation.x = -swing * 0.5;
        this.armR.rotation.x = 0.25 + swing * 0.5;
      }
    } else {
      this.legL.rotation.x = damp(this.legL.rotation.x, 0, 8, dt);
      this.legR.rotation.x = damp(this.legR.rotation.x, 0, 8, dt);
    }
    this.head.rotation.x = damp(this.head.rotation.x, -clamp((player.position.y - p.y) * 0.05, -0.2, 0.3), 6, dt);
    // subtle idle breathing
    this.bodyRoot.position.y = Math.sin(time * 1.7 + this.walkPhase) * 0.012;
    this.gun.position.y = 1.24 + Math.sin(time * 1.7 + this.walkPhase) * 0.01;

    if (this.flashTimer > 0) {
      this.flashTimer -= dt;
      if (this.flashTimer <= 0) this.flash.visible = false;
    }
    if (this.healthSprite.visible && this.hp >= this.maxHp) this.healthSprite.visible = false;
  }

  dispose() {
    this.group.traverse((o) => {
      if (o.isMesh) {
        o.geometry?.dispose?.();
        if (Array.isArray(o.material)) o.material.forEach(m => m.dispose?.());
        else o.material?.dispose?.();
      }
    });
    this.healthTex?.dispose();
  }
}

export { BOT_NAMES };

import * as THREE from 'three';
import { clamp, damp, lerp, randRange } from './utils.js';
import { WEAPONS, buildWeapon, createMuzzleFlash } from './weapons.js';

const EYE = 1.66;

export class Player {
  constructor(scene, camera, world, audio, effects, hud) {
    this.scene = scene;
    this.camera = camera;
    this.world = world;
    this.audio = audio;
    this.effects = effects;
    this.hud = hud;

    this.position = new THREE.Vector3(world.playerSpawn.x, world.playerSpawn.y, world.playerSpawn.z);
    this.velocity = new THREE.Vector3();
    this.yaw = 0.0;
    this.pitch = 0.0;
    this.eye = EYE;
    this.crouchEye = 1.15;
    this.health = 100;
    this.maxHealth = 100;
    this.armor = 50;
    this.maxArmor = 100;
    this.grounded = true;
    this.isMoving = false;
    this.isSprinting = false;
    this.crouching = false;
    this.alive = true;
    this.sensitivity = 1;
    this.enabled = false;
    this.fovBase = 72;
    this.fovAds = 52;

    this.weapons = {
      rifle: { ...WEAPONS.rifle, mag: WEAPONS.rifle.magSize, reserve: WEAPONS.rifle.reserve, model: null },
      smg: { ...WEAPONS.smg, mag: WEAPONS.smg.magSize, reserve: WEAPONS.smg.reserve, model: null }
    };
    this.order = ['rifle', 'smg'];
    this.currentIndex = 0;
    this.reloading = false;
    this.reloadTimer = 0;
    this.fireCooldown = 0;
    this.ads = false;
    this.adsT = 0;
    this.recoilPitch = 0;
    this.recoilYaw = 0;
    this.viewKick = 0;
    this.shake = 0;
    this.bobPhase = 0;
    this.bobAmount = 0;
    this.stepTimer = 0;
    this.lastDamageTime = 99;
    this.timeSinceDamage = 99;
    this.stats = { shots: 0, hits: 0, kills: 0, damage: 0 };
    this.weaponSwitching = 0;
    this.hitPoint = new THREE.Vector3();
    this._forward = new THREE.Vector3();
    this._right = new THREE.Vector3();
    this._raycaster = new THREE.Raycaster();
    this._raycaster.far = 300;
    this._muzzleWorld = new THREE.Vector3();
    this._euler = new THREE.Euler(0, 0, 0, 'YXZ');
    this._lastPos = this.position.clone();

    // view model
    this.viewRoot = new THREE.Group();
    camera.add(this.viewRoot);
    scene.add(camera);
    this.currentModel = null;
    this._buildViewModels();

    this.muzzleFlash = createMuzzleFlash();
    this.viewRoot.add(this.muzzleFlash.sprite);
    this.muzzleLight = new THREE.PointLight(0xffa75a, 0, 7, 2);
    camera.add(this.muzzleLight);
    this.flashTimer = 0;

    // pickups
    this.pickups = [];
    this._buildPickups();
    this.nearbyPickup = null;

    // landing / menu camera support
    this.spawn = this.position.clone();
  }

  _buildViewModels() {
    for (const key of this.order) {
      const model = buildWeapon(key);
      model.visible = false;
      model.traverse(o => { if (o.isMesh) { o.castShadow = false; o.receiveShadow = false; o.frustumCulled = false; } });
      model.userData.base = key;
      this.weapons[key].model = model;
      this.viewRoot.add(model);
      // muzzle flash sprite + light parented to this model
      this.weapons[key].muzzle.add(this.muzzleFlash.sprite);
      this.muzzleFlash.sprite.position.set(0, 0, -0.02);
    }
    this.currentModel = this.weapons[this.order[0]].model;
    this.currentModel.visible = true;

    this.hipPos = new THREE.Vector3(0.29, -0.27, -0.52);
    this.adsPos = new THREE.Vector3(0.0, -0.14, -0.33);
    this.viewRoot.position.copy(this.hipPos);
    this.viewRoot.rotation.set(0.015, -0.04, 0);
  }

  _buildPickups() {
    const tex = (() => {
      const c = document.createElement('canvas'); c.width = c.height = 64;
      const ctx = c.getContext('2d');
      const g = ctx.createRadialGradient(32, 32, 0, 32, 32, 32);
      g.addColorStop(0, 'rgba(255,255,255,0.95)');
      g.addColorStop(0.3, 'rgba(255,220,150,0.5)');
      g.addColorStop(1, 'rgba(255,160,50,0)');
      ctx.fillStyle = g; ctx.fillRect(0, 0, 64, 64);
      const t = new THREE.CanvasTexture(c); t.colorSpace = THREE.SRGBColorSpace; return t;
    })();
    const colors = { ammo: 0xffb24d, med: 0x53e08f, armor: 0x50b9ff };
    for (const spot of this.world.lootSpots) {
      const type = spot.type;
      const group = new THREE.Group();
      const color = colors[type];
      const boxMat = new THREE.MeshStandardMaterial({ color, emissive: color, emissiveIntensity: 0.45, roughness: 0.4, metalness: 0.35 });
      const dark = new THREE.MeshStandardMaterial({ color: 0x1c2223, roughness: 0.7, metalness: 0.3 });
      let mesh;
      if (type === 'med') {
        mesh = new THREE.Mesh(new THREE.BoxGeometry(0.42, 0.32, 0.42), new THREE.MeshStandardMaterial({ color: 0xe8ebe7, roughness: 0.55 }));
        const crossMat = new THREE.MeshStandardMaterial({ color: 0xff4d3d, emissive: 0x5a0a05, emissiveIntensity: 0.8 });
        group.add(mesh);
        const c1 = new THREE.Mesh(new THREE.BoxGeometry(0.2, 0.06, 0.43), crossMat);
        c1.position.z = 0.001; group.add(c1);
        const c2 = new THREE.Mesh(new THREE.BoxGeometry(0.06, 0.2, 0.43), crossMat);
        c2.position.z = 0.001; group.add(c2);
      } else if (type === 'armor') {
        mesh = new THREE.Mesh(new THREE.OctahedronGeometry(0.24, 0), boxMat);
        group.add(mesh);
        const ring = new THREE.Mesh(new THREE.TorusGeometry(0.3, 0.02, 5, 18), dark);
        ring.rotation.x = Math.PI / 2; group.add(ring);
      } else {
        mesh = new THREE.Mesh(new THREE.BoxGeometry(0.44, 0.26, 0.3), boxMat);
        group.add(mesh);
        const b1 = new THREE.Mesh(new THREE.BoxGeometry(0.46, 0.04, 0.32), dark);
        b1.position.y = 0.14; group.add(b1);
        const b2 = b1.clone(); b2.position.y = -0.14; group.add(b2);
      }
      const glow = new THREE.Sprite(new THREE.SpriteMaterial({
        map: tex, color, transparent: true, opacity: 0.75, depthWrite: false, blending: THREE.AdditiveBlending
      }));
      glow.scale.setScalar(1.5);
      glow.position.y = -0.15;
      group.add(glow);
      group.position.set(spot.x, spot.y + 0.45, spot.z);
      group.userData = { type, taken: false, baseY: spot.y + 0.45, phase: Math.random() * 6 };
      this.scene.add(group);
      this.pickups.push(group);
    }
  }

  reset() {
    this.position.copy(this.spawn);
    this.position.y = this.world.heightAt(this.spawn.x, this.spawn.z);
    this.velocity.set(0, 0, 0);
    this.yaw = this.world.playerSpawn.yaw ?? 0.15;
    this.pitch = 0;
    this.health = this.maxHealth;
    this.armor = 50;
    this.alive = true;
    this.reloading = false;
    this.reloadTimer = 0;
    this.fireCooldown = 0;
    this.adsT = 0;
    this.recoilPitch = 0;
    this.recoilYaw = 0;
    this.stats = { shots: 0, hits: 0, kills: 0, damage: 0 };
    for (const key of this.order) {
      const w = this.weapons[key];
      w.mag = w.magSize; w.reserve = WEAPONS[key].reserve;
    }
    this.currentIndex = 0;
    this._selectModel();
    this.viewRoot.visible = true;
    for (const p of this.pickups) {
      p.visible = true;
      p.userData.taken = false;
    }
    this.camera.fov = this.fovBase;
    this.camera.updateProjectionMatrix();
    this.timeSinceDamage = 99;
    this.lastDamageTime = 99;
  }

  get weapon() { return this.weapons[this.order[this.currentIndex]]; }

  _selectModel() {
    for (const key of this.order) this.weapons[key].model.visible = false;
    const m = this.weapon.model;
    m.visible = true;
    this.currentModel = m;
    m.userData.magGroup.rotation.x = 0;
  }

  look(dx, dy, sensitivity) {
    if (!this.alive) return;
    const s = 0.0022 * sensitivity * (this.adsT > 0.5 ? 0.72 : 1);
    this.yaw -= dx * s;
    this.pitch -= dy * s;
    this.pitch = clamp(this.pitch, -1.42, 1.42);
  }

  update(dt, input, time) {
    if (!this.enabled) return;
    this.timeSinceDamage += dt;
    if (this.alive && this.timeSinceDamage > 6 && this.health < this.maxHealth) {
      this.health = Math.min(this.maxHealth, this.health + 7 * dt);
    }

    const forward = this._forward.set(-Math.sin(this.yaw), 0, -Math.cos(this.yaw));
    const right = this._right.set(Math.cos(this.yaw), 0, -Math.sin(this.yaw));

    const move = new THREE.Vector3();
    if (input.forward) move.add(forward);
    if (input.back) move.sub(forward);
    if (input.right) move.add(right);
    if (input.left) move.sub(right);
    const wantsMove = move.lengthSq() > 0.001;
    if (wantsMove) move.normalize();

    this.crouching = input.crouch;
    this.isSprinting = input.sprint && !this.crouching && wantsMove && !this.ads;
    const targetSpeed = this.crouching ? 2.6 : this.isSprinting ? 8.0 : 5.1;
    const accel = this.grounded ? 12 : 3.5;
    const targetVX = move.x * targetSpeed;
    const targetVZ = move.z * targetSpeed;
    this.velocity.x = damp(this.velocity.x, targetVX, accel, dt);
    this.velocity.z = damp(this.velocity.z, targetVZ, accel, dt);

    if (input.jump && this.grounded && !this.crouching) {
      this.velocity.y = 7.2;
      this.grounded = false;
      this.audio.jump();
      input.jump = false;
    }
    this.velocity.y -= 21 * dt;

    const oldX = this.position.x, oldZ = this.position.z;
    let nx = this.position.x + this.velocity.x * dt;
    let nz = this.position.z + this.velocity.z * dt;

    // circular colliders
    for (const c of this.world.colliders) {
      const dx = nx - c.x, dz = nz - c.z;
      const d2 = dx * dx + dz * dz;
      const min = c.r + 0.38;
      if (d2 < min * min && d2 > 0.000001) {
        const d = Math.sqrt(d2);
        nx = c.x + (dx / d) * min;
        nz = c.z + (dz / d) * min;
      }
    }
    // keep player on the island
    if (this.world.heightAt(nx, nz) < -1.2) {
      const a = Math.atan2(-nz, -nx);
      nx = Math.cos(a) * 128;
      nz = Math.sin(a) * 128;
    }
    this.position.x = nx;
    this.position.z = nz;
    this.position.y += this.velocity.y * dt;

    const ground = this.world.heightAt(this.position.x, this.position.z);
    if (this.position.y <= ground) {
      if (!this.grounded) this.audio.land();
      const fallSpeed = -this.velocity.y;
      if (fallSpeed > 9) { this.shake = Math.min(0.5, fallSpeed * 0.02); }
      this.position.y = ground;
      this.velocity.y = 0;
      this.grounded = true;
    } else {
      this.grounded = false;
    }

    const realSpeed = Math.hypot(this.position.x - oldX, this.position.z - oldZ) / Math.max(dt, 0.0001);
    this.isMoving = realSpeed > 0.4;

    // footsteps
    if (this.grounded && this.isMoving) {
      this.stepTimer -= dt * (this.isSprinting ? 1.65 : 1.15);
      if (this.stepTimer <= 0) {
        this.stepTimer = 0.42;
        this.audio.step(this.isSprinting);
      }
      this.bobPhase += dt * (this.isSprinting ? 13 : 9.2);
      this.bobAmount = damp(this.bobAmount, this.crouching ? 0.3 : this.isSprinting ? 1 : 0.7, 6, dt);
    } else {
      this.bobAmount = damp(this.bobAmount, 0, 8, dt);
      this.bobPhase += dt * 1.2;
    }

    // ADS / FOV
    this.ads = input.aim && !this.reloading && this.alive;
    this.adsT = damp(this.adsT, this.ads ? 1 : 0, 13, dt);
    const targetFov = lerp(this.fovBase, this.fovAds, this.adsT);
    this.camera.fov = damp(this.camera.fov, targetFov, 10, dt);
    this.camera.updateProjectionMatrix();

    // weapon timers
    this.fireCooldown = Math.max(0, this.fireCooldown - dt);
    if (this.reloading) {
      this.reloadTimer -= dt;
      if (this.reloadTimer <= 0) this._finishReload();
    }
    if (this.weaponSwitching > 0) this.weaponSwitching -= dt;

    // shooting
    if (input.fire && this.alive && !this.reloading && this.weaponSwitching <= 0) {
      const w = this.weapon;
      this.fireInterval = 60 / w.rpm;
      if (this.fireCooldown <= 0 && w.mag > 0) {
        this._shoot(time);
      } else if (w.mag <= 0 && !this.reloading) {
        this.startReload();
      }
    }
    if (input.reloadJust) {
      this.startReload();
      input.reloadJust = false;
    }
    if (input.swapJust) {
      this.switchWeapon(this.currentIndex === 0 ? 1 : 0);
      input.swapJust = false;
    }
    if (input.weapon1Just) { this.switchWeapon(0); input.weapon1Just = false; }
    if (input.weapon2Just) { this.switchWeapon(1); input.weapon2Just = false; }
    if (input.interactJust) { this.interact(); input.interactJust = false; }

    // recoil recovery
    this.recoilPitch = damp(this.recoilPitch, 0, 9, dt);
    this.recoilYaw = damp(this.recoilYaw, 0, 9, dt);
    this.viewKick = damp(this.viewKick, 0, 14, dt);
    this.shake = damp(this.shake, 0, 6, dt);

    // camera transform
    const bobY = Math.sin(this.bobPhase * 2) * 0.022 * this.bobAmount;
    const bobX = Math.cos(this.bobPhase) * 0.026 * this.bobAmount;
    const eyeTarget = this.crouching ? this.crouchEye : EYE;
    this.eye = damp(this.eye, eyeTarget, 12, dt);
    const shakeX = (Math.random() - 0.5) * this.shake * 0.02;
    const shakeY = (Math.random() - 0.5) * this.shake * 0.02;
    this.camera.position.set(this.position.x + bobX * 0.35, this.position.y + this.eye + bobY, this.position.z);
    this._euler.set(this.pitch + this.recoilPitch + this.viewKick * 0.1 + shakeY, this.yaw + this.recoilYaw + shakeX, Math.sin(this.bobPhase) * 0.004 * this.bobAmount);
    this.camera.rotation.copy(this._euler);

    // weapon viewmodel
    const hip = this.hipPos;
    const ads = this.adsPos;
    const targetX = lerp(hip.x, ads.x, this.adsT);
    const targetY = lerp(hip.y, ads.y, this.adsT);
    const targetZ = lerp(hip.z, ads.z, this.adsT);
    const swayX = Math.cos(this.bobPhase) * 0.012 * this.bobAmount;
    const swayY = Math.sin(this.bobPhase * 2) * 0.009 * this.bobAmount;
    const switchDrop = this.weaponSwitching > 0 ? this.weaponSwitching * 0.9 : 0;
    const reloadDrop = this.reloading ? Math.sin(clamp(this.reloadTimer / this.weapon.reloadTime, 0, 1) * Math.PI) * 0.12 : 0;
    this.viewRoot.position.x = damp(this.viewRoot.position.x, targetX + swayX * (1 - this.adsT), 16, dt);
    this.viewRoot.position.y = damp(this.viewRoot.position.y, targetY + swayY * (1 - this.adsT) - switchDrop - reloadDrop, 16, dt);
    this.viewRoot.position.z = damp(this.viewRoot.position.z, targetZ + this.viewKick * 0.12, 18, dt);
    this.viewRoot.rotation.x = damp(this.viewRoot.rotation.x, this.viewKick * 1.2 + (this.adsT ? 0 : 0.015), 14, dt);
    this.viewRoot.rotation.y = damp(this.viewRoot.rotation.y, lerp(-0.045, 0, this.adsT), 12, dt);
    this.viewRoot.rotation.z = damp(this.viewRoot.rotation.z, lerp(0.01, 0, this.adsT) + swayX * 0.3, 12, dt);
    if (this.reloading) {
      const t = this.reloadTimer / this.weapon.reloadTime;
      this.currentModel.userData.magGroup.rotation.x = Math.sin(t * Math.PI) * 0.5;
      this.currentModel.userData.magGroup.position.y = -Math.sin(t * Math.PI) * 0.12;
    } else if (this.currentModel) {
      this.currentModel.userData.magGroup.rotation.x = damp(this.currentModel.userData.magGroup.rotation.x, 0, 10, dt);
      this.currentModel.userData.magGroup.position.y = damp(this.currentModel.userData.magGroup.position.y, 0, 10, dt);
    }

    if (this.flashTimer > 0) {
      this.flashTimer -= dt;
      if (this.flashTimer <= 0) {
        this.muzzleFlash.sprite.visible = false;
        this.muzzleLight.intensity = 0;
      }
    }

    // pickups
    this.nearbyPickup = null;
    let best = 2.2;
    for (const p of this.pickups) {
      if (p.userData.taken) continue;
      p.rotation.y += dt * 1.6;
      p.position.y = p.userData.baseY + Math.sin(time * 1.8 + p.userData.phase) * 0.08;
      p.children[0].rotation.y += dt * 0.7;
      const d = Math.hypot(p.position.x - this.position.x, p.position.z - this.position.z);
      if (d < best) { best = d; this.nearbyPickup = p; }
    }

    this.updateHud();
  }

  _shoot(time) {
    const w = this.weapon;
    w.mag--;
    this.fireCooldown = 60 / w.rpm;
    this.stats.shots++;
    this.flashTimer = 0.045;
    this.muzzleFlash.sprite.visible = true;
    this.muzzleFlash.sprite.material.rotation = Math.random() * 6.28;
    this.muzzleFlash.sprite.scale.setScalar(0.26 + Math.random() * 0.16);
    this.muzzleLight.intensity = 3.2;
    this.currentModel.userData.muzzle.getWorldPosition(this._muzzleWorld);
    this.muzzleLight.position.copy(this._muzzleWorld);
    this.audio.shot(w.sound);

    // spread
    const movingPenalty = this.isMoving ? w.moveSpread : 0;
    const spread = lerp(w.spread + movingPenalty, w.adsSpread, this.adsT) * (this.crouching ? 0.8 : 1);
    const dir = new THREE.Vector3(0, 0, -1).applyQuaternion(this.camera.quaternion);
    dir.x += (Math.random() - 0.5) * spread * 2;
    dir.y += (Math.random() - 0.5) * spread * 2;
    dir.z += (Math.random() - 0.5) * spread * 2;
    dir.normalize();
    this._raycaster.set(this.camera.position.clone(), dir);
    this._raycaster.far = w.range;

    let hitPoint = null;
    let enemyHit = null;
    const enemyIntersect = this.enemyManager?.raycast(this._raycaster);
    const worldHits = this._raycaster.intersectObjects(this.world.collisionMeshes, true);
    let worldHit = null;
    for (const h of worldHits) {
      if (h.distance < 0.35) continue;
      worldHit = h; break;
    }
    if (enemyIntersect && (!worldHit || enemyIntersect.distance < worldHit.distance)) {
      enemyHit = enemyIntersect;
      hitPoint = enemyIntersect.point;
    } else if (worldHit) {
      hitPoint = worldHit.point;
    }
    if (!hitPoint) hitPoint = this.camera.position.clone().addScaledVector(dir, w.range);

    this.effects.tracer(this._muzzleWorld, hitPoint);
    this.effects.muzzleSmoke(this._muzzleWorld, dir);
    if (enemyHit) {
      const part = enemyHit.object.userData.part;
      const dmg = w.damage * (part === 'head' ? 1.0 : 1.0);
      const killed = enemyHit.object.userData.enemy.hit(dmg, part, hitPoint);
      this.stats.hits++;
      this.stats.damage += dmg;
      this.effects.blood(hitPoint, dir);
      this.hud?.hitmarker(part === 'head');
      this.hud?.damageNumber(hitPoint, Math.round(dmg * (part === 'head' ? w.headMult : 1)), part === 'head', killed);
      this.audio.hitmarker(part === 'head');
      if (killed) {
        this.stats.kills++;
        this.audio.kill();
        this.onKill?.(enemyHit.object.userData.enemy);
      }
    } else {
      const normal = worldHit?.face?.normal?.clone() || new THREE.Vector3(0, 1, 0);
      if (worldHit?.face) normal.transformDirection(worldHit.object.matrixWorld);
      this.effects.impact(hitPoint, normal, 'world');
    }

    // shell + recoil
    const shellPos = this.currentModel.userData.muzzle.getWorldPosition(new THREE.Vector3());
    const right = new THREE.Vector3(1, 0.2, 0.2).applyQuaternion(this.camera.quaternion);
    shellPos.addScaledVector(right, -0.18);
    this.effects.shell(shellPos, right.multiplyScalar(1.4 + Math.random()));
    const recoilMul = this.adsT ? 0.72 : 1;
    this.recoilPitch += w.recoil * recoilMul * (0.8 + Math.random() * 0.4);
    this.recoilYaw += (Math.random() - 0.5) * w.recoil * 0.7 * recoilMul;
    this.viewKick += 0.06;
    this.shake = Math.max(this.shake, 0.12);

    // auto reload
    if (w.mag <= 0) this.startReload();
  }

  startReload() {
    if (this.reloading || !this.alive) return;
    const w = this.weapon;
    if (w.mag >= w.magSize || w.reserve <= 0) return;
    this.reloading = true;
    this.reloadTimer = w.reloadTime;
    this.audio.reload();
  }

  _finishReload() {
    const w = this.weapon;
    const need = w.magSize - w.mag;
    const take = Math.min(need, w.reserve);
    w.mag += take;
    w.reserve -= take;
    this.reloading = false;
    this.reloadTimer = 0;
  }

  switchWeapon(index) {
    if (index === this.currentIndex || !this.alive) return;
    this.currentIndex = index;
    this.weaponSwitching = 0.28;
    this.reloading = false;
    this.reloadTimer = 0;
    this._selectModel();
    this.audio.equip();
  }

  interact() {
    if (this.nearbyPickup && !this.nearbyPickup.userData.taken) {
      const p = this.nearbyPickup;
      const type = p.userData.type;
      if (type === 'med') {
        this.heal(45);
        this.hud?.toast('KIT MÉDICO', '+45 VIDA');
      } else if (type === 'armor') {
        this.armor = Math.min(this.maxArmor, this.armor + 50);
        this.hud?.toast('COLETE', '+50 BLINDAGEM');
      } else {
        const w = this.weapon;
        w.reserve = Math.min(999, w.reserve + 60);
        this.hud?.toast('MUNIÇÃO', `+60 ${w.short}`);
      }
      this.audio.pickup();
      p.userData.taken = true;
      p.visible = false;
      this.nearbyPickup = null;
    }
  }

  damage(amount, fromPos) {
    if (!this.alive) return;
    let dmg = amount;
    if (this.armor > 0) {
      const absorbed = Math.min(this.armor, dmg * 0.58);
      this.armor -= absorbed;
      dmg -= absorbed;
    }
    this.health -= dmg;
    this.timeSinceDamage = 0;
    this.shake = Math.max(this.shake, 0.35);
    this.audio.hurt();
    this.hud?.damageFlash(fromPos, this.position, this.yaw);
    if (this.health <= 0) {
      this.health = 0;
      this.alive = false;
      this.onDeath?.();
    }
  }

  zoneDamage(amount) {
    if (!this.alive) return;
    this.health -= amount;
    this.timeSinceDamage = 0;
    if (this.health <= 0) {
      this.health = 0;
      this.alive = false;
      this.onDeath?.();
    }
  }

  heal(amount) {
    this.health = Math.min(this.maxHealth, this.health + amount);
  }

  addAmmo(amount) {
    for (const key of this.order) {
      this.weapons[key].reserve = Math.min(999, this.weapons[key].reserve + amount);
    }
  }

  updateHud() {
    if (!this.hud) return;
    this.hud.setHealth(this.health, this.maxHealth, this.armor, this.maxArmor);
    const w = this.weapon;
    this.hud.setWeapon(w, this.currentIndex, this.reloading, this.reloadTimer);
    this.hud.setCrosshair(this.adsT, this.isMoving, this.isSprinting, this.recoilPitch);
    this.hud.setPrompt(this.nearbyPickup, this.nearbyPickup?.userData.type);
    this.hud.setPosition(this.position, this.yaw);
  }
}

