import { clamp } from './utils.js';
import { WEAPONS } from './weapons.js';

const $ = (id) => document.getElementById(id);

export class HUD {
  constructor(world, camera) {
    this.world = world;
    this.camera = camera;
    this.el = {
      hud: $('hud'),
      compassStrip: $('compassStrip'),
      zoneTimer: $('zoneTimer'),
      zoneState: $('zoneState'),
      aliveNum: $('aliveNum'),
      killCount: $('killCount'),
      minimap: $('minimap'),
      minimapCoords: $('minimapCoords'),
      healthBar: $('healthBar'),
      healthText: $('healthText'),
      armorBar: $('armorBar'),
      armorText: $('armorText'),
      weaponName: $('weaponName'),
      weaponMode: $('fireMode'),
      ammoMag: $('ammoMag'),
      ammoReserve: $('ammoReserve'),
      magPips: $('magPips'),
      slot1: $('slot1'),
      slot2: $('slot2'),
      killfeed: $('killfeed'),
      crosshair: $('crosshair'),
      hitmarker: $('hitmarker'),
      toast: $('toast'),
      prompt: $('pickupPrompt'),
      promptText: $('pickupText'),
      damageNumbers: $('damageNumbers'),
      damageDirs: $('damageDirs'),
      danger: $('dangerVignette'),
      zoneWarning: $('zoneWarning'),
      fireMode: $('fireMode'),
      debug: $('debug'),
      lockHint: $('lockHint')
    };
    this.ctx = this.el.minimap.getContext('2d');
    this.minimapSize = 240;
    this.zone = null;
    this.toastTimer = 0;
    this.toasts = [];
    this.lastHealth = 100;
    this.lastAmmo = 30;
    this._buildCompass();
    this._drawBriefMap();
    this.playerPos = { x: 0, z: 0 };
    this.playerYaw = 0;
    this.enemies = [];
    this.time = 0;
  }

  _buildCompass() {
    const strip = this.el.compassStrip;
    strip.innerHTML = '';
    const labels = { 0: 'N', 45: 'NE', 90: 'L', 135: 'SE', 180: 'S', 225: 'SO', 270: 'O', 315: 'NO' };
    for (let i = 0; i < 80; i++) {
      const deg = ((i * 11.25) - 180 + 360) % 360;
      const tick = document.createElement('span');
      const norm = Math.round(deg * 100) / 100;
      const key = Math.round(norm / 45) * 45 % 360;
      const isMajor = Math.abs(norm - key) < 0.1 || Math.abs(norm - 360) < 0.1;
      tick.className = 'compass-tick' + (isMajor ? ' major' : '');
      tick.dataset.deg = deg;
      tick.innerHTML = `<em>${isMajor ? (labels[key] ?? '') : ''}</em><i></i>`;
      strip.appendChild(tick);
    }
    strip.style.transform = 'translateX(-17px)';
    this.compassEls = [...strip.children];
    const style = document.createElement('style');
    style.textContent = '.compass-tick em{font-style:normal;font-size:9px;line-height:1;color:inherit}';
    document.head.appendChild(style);
  }

  _drawBriefMap() {
    const canvas = document.getElementById('briefMap');
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    const s = canvas.width;
    ctx.clearRect(0, 0, s, s);
    ctx.drawImage(this.world.mapCanvas, 0, 0, s, s);
    ctx.strokeStyle = 'rgba(255,170,60,0.5)';
    ctx.lineWidth = 1.5;
    ctx.setLineDash([4, 6]);
    ctx.beginPath(); ctx.arc(s / 2, s / 2, s * 0.32, 0, Math.PI * 2); ctx.stroke();
    ctx.setLineDash([]);
    ctx.strokeStyle = 'rgba(56,224,207,0.7)';
    ctx.beginPath(); ctx.arc(s * 0.42, s * 0.38, s * 0.15, 0, Math.PI * 2); ctx.stroke();
    ctx.fillStyle = 'rgba(255,255,255,0.85)';
    for (const poi of this.world.pois) {
      const x = (poi.x / this.world.mapExtent + 0.5) * s;
      const z = (poi.z / this.world.mapExtent + 0.5) * s;
      ctx.fillRect(x - 2, z - 2, 4, 4);
    }
    // drop route
    ctx.strokeStyle = 'rgba(255,210,120,0.75)';
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.moveTo(s * 0.48, s * 0.9);
    ctx.bezierCurveTo(s * 0.55, s * 0.7, s * 0.45, s * 0.45, s * 0.62, s * 0.18);
    ctx.stroke();
    ctx.fillStyle = '#ffb24d';
    ctx.beginPath(); ctx.arc(s * 0.48, s * 0.9, 4, 0, Math.PI * 2); ctx.fill();
  }

  show() { this.el.hud.hidden = false; }
  hide() { this.el.hud.hidden = true; }

  setZone(zone) { this.zone = zone; }

  setAlive(n, total) {
    this.el.aliveNum.textContent = String(n).padStart(2, '0');
  }

  setKills(n) { this.el.killCount.textContent = n; }

  setZoneUi(timeLeft, closing) {
    const m = Math.floor(Math.max(0, timeLeft) / 60);
    const s = Math.floor(Math.max(0, timeLeft) % 60);
    this.el.zoneTimer.textContent = `${String(m).padStart(2, '0')}:${String(s).padStart(2, '0')}`;
    this.el.zoneState.textContent = closing ? 'FECHANDO' : 'ESTÁVEL';
    this.el.zoneState.classList.toggle('closing', !!closing);
  }

  setHealth(hp, maxHp, armor, maxArmor) {
    const pct = clamp(hp / maxHp, 0, 1) * 100;
    this.el.healthBar.style.width = `${pct}%`;
    this.el.healthText.textContent = Math.ceil(hp);
    this.el.armorBar.style.width = `${clamp(armor / maxArmor, 0, 1) * 100}%`;
    this.el.armorText.textContent = Math.ceil(armor);
    this.el.healthBar.parentElement.classList.toggle('low', hp < 30);
  }

  setWeapon(w, index, reloading, reloadTimer) {
    this.el.weaponName.textContent = reloading ? 'RECARREGANDO…' : w.name;
    this.el.fireMode.textContent = w.mode;
    this.el.ammoMag.textContent = w.mag;
    this.el.ammoReserve.textContent = w.reserve;
    this.el.ammoMag.style.color = w.mag <= Math.ceil(w.magSize * 0.25) ? '#ff5a3c' : '';
    this.el.slot1.classList.toggle('active', index === 0);
    this.el.slot2.classList.toggle('active', index === 1);
    if (this.el.magPips.childElementCount !== w.magSize) {
      this.el.magPips.innerHTML = '';
      for (let i = 0; i < w.magSize; i++) this.el.magPips.appendChild(document.createElement('i'));
    }
    if (this.lastAmmo !== w.mag) {
      [...this.el.magPips.children].forEach((pip, i) => pip.classList.toggle('empty', i >= w.mag));
      this.lastAmmo = w.mag;
    }
  }

  setCrosshair(adsT, moving, sprinting, recoil) {
    const spread = 7 + (moving ? 4 : 0) + (sprinting ? 8 : 0) + Math.min(18, recoil * 900);
    this.el.crosshair.style.setProperty('--spread', `${spread}px`);
    this.el.crosshair.classList.toggle('hidden', adsT > 0.6);
  }

  setPrompt(pickup, type) {
    if (pickup) {
      const label = type === 'med' ? 'KIT MÉDICO' : type === 'armor' ? 'COLETE' : 'MUNIÇÃO';
      this.el.promptText.textContent = `SAQUEAR ${label}`;
      this.el.prompt.classList.add('show');
    } else {
      this.el.prompt.classList.remove('show');
    }
  }

  setPosition(pos, yaw) {
    this.playerPos.x = pos.x; this.playerPos.z = pos.z;
    this.playerYaw = yaw;
    this.el.minimapCoords.textContent = `X ${String(Math.round(pos.x)).padStart(3, '0')} · Z ${String(Math.round(pos.z)).padStart(3, '0')}`;
  }

  setCompass(yaw) {
    const heading = ((-yaw * 180 / Math.PI) % 360 + 360) % 360;
    const offset = -((heading + 180) / 11.25) * 34 - 17;
    this.el.compassStrip.style.transform = `translateX(${offset}px)`;
  }

  setEnemies(list) { this.enemies = list; }

  hitmarker(head) {
    const el = this.el.hitmarker;
    el.classList.remove('show');
    el.classList.toggle('head', !!head);
    void el.offsetWidth;
    el.classList.add('show');
  }

  damageNumber(worldPos, amount, head, killed) {
    const v = worldPos.clone().project(this.camera);
    if (v.z > 1) return;
    const x = (v.x * 0.5 + 0.5) * window.innerWidth;
    const y = (-v.y * 0.5 + 0.5) * window.innerHeight;
    const el = document.createElement('div');
    el.className = 'dmg-num' + (head ? ' head' : '') + (killed ? ' kill' : '');
    el.textContent = killed ? 'ELIMINADO' : String(amount);
    el.style.left = `${x + (Math.random() - 0.5) * 24}px`;
    el.style.top = `${y + (Math.random() - 0.5) * 14}px`;
    this.el.damageNumbers.appendChild(el);
    setTimeout(() => el.remove(), 900);
  }

  damagedFrom(fromPos) {
    if (!fromPos) return;
    const dx = fromPos.x - this.playerPos.x;
    const dz = fromPos.z - this.playerPos.z;
    const bearing = Math.atan2(dx, dz);
    const deg = (bearing - this.playerYaw - Math.PI) * 180 / Math.PI;
    const el = document.createElement('div');
    el.className = 'dir-mark';
    el.style.setProperty('--rot', `${deg.toFixed(1)}deg`);
    this.el.damageDirs.appendChild(el);
    setTimeout(() => el.remove(), 1250);
  }

  damageFlash(fromPos, playerPos, yaw) {
    this.damagedFrom(fromPos);
    const v = this.el.danger;
    v.classList.add('hit');
    setTimeout(() => v.classList.remove('hit'), 110);
  }

  killfeed(killer, victim, weapon, head = false, you = false) {
    const el = document.createElement('div');
    el.className = 'feed-item' + (head ? ' head' : '');
    el.innerHTML = `<span class="${you ? 'you' : ''}">${killer}</span><span class="gun">[${weapon}]</span><span>${victim}</span>`;
    this.el.killfeed.appendChild(el);
    while (this.el.killfeed.childElementCount > 5) this.el.killfeed.firstElementChild.remove();
    setTimeout(() => el.remove(), 6500);
  }

  toast(title, sub) {
    const line = document.createElement('div');
    line.className = 'toast-line';
    line.innerHTML = `<b>${title}</b>${sub ? `<span>${sub}</span>` : ''}`;
    this.el.toast.appendChild(line);
    this.el.toast.classList.add('show');
    clearTimeout(this._toastTimer);
    this._toastTimer = setTimeout(() => {
      this.el.toast.classList.remove('show');
      setTimeout(() => line.remove(), 300);
    }, 1900);
    while (this.el.toast.childElementCount > 2) this.el.toast.firstElementChild.remove();
  }

  zoneWarning(show) {
    this.el.zoneWarning.classList.toggle('show', show);
  }

  lockHint(show) {
    this.el.lockHint.classList.toggle('show', show);
  }

  update(time, dt) {
    this.time = time;
    this.setCompass(this.playerYaw);
    this._drawMinimap();
  }

  _drawMinimap() {
    const ctx = this.ctx;
    const s = this.minimapSize;
    const size = s;
    ctx.clearRect(0, 0, s, s);
    ctx.save();
    ctx.beginPath();
    ctx.arc(s / 2, s / 2, s / 2 - 2, 0, Math.PI * 2);
    ctx.clip();
    ctx.drawImage(this.world.mapCanvas, 0, 0, s, s);

    const toMap = (x, z) => [((x / this.world.mapExtent + 0.5) * s), ((z / this.world.mapExtent + 0.5) * s)];

    // zone
    if (this.zone) {
      const [zx, zy] = toMap(this.zone.center.x, this.zone.center.z);
      const zr = (this.zone.radius / this.world.mapExtent) * s;
      ctx.fillStyle = 'rgba(7,10,12,0.45)';
      ctx.beginPath();
      ctx.rect(0, 0, s, s);
      ctx.arc(zx, zy, zr, 0, Math.PI * 2, true);
      ctx.fill();
      ctx.strokeStyle = 'rgba(255,164,60,0.95)';
      ctx.lineWidth = 2;
      ctx.beginPath(); ctx.arc(zx, zy, zr, 0, Math.PI * 2); ctx.stroke();
      if (this.zone.nextRadius && this.zone.nextRadius < this.zone.radius) {
        ctx.strokeStyle = 'rgba(84,215,255,0.75)';
        ctx.setLineDash([5, 5]);
        ctx.lineWidth = 1.2;
        ctx.beginPath(); ctx.arc(zx, zy, (this.zone.nextRadius / this.world.mapExtent) * s, 0, Math.PI * 2); ctx.stroke();
        ctx.setLineDash([]);
      }
    }

    // POIs
    ctx.fillStyle = 'rgba(255,255,255,0.7)';
    ctx.font = '700 8px Rajdhani, sans-serif';
    ctx.textAlign = 'center';
    for (const poi of this.world.pois) {
      const [x, y] = toMap(poi.x, poi.z);
      ctx.fillRect(x - 1.5, y - 1.5, 3, 3);
    }

    // enemies (only nearby — radar range)
    for (const e of this.enemies) {
      if (e.dead) continue;
      const dx = e.group.position.x - this.playerPos.x;
      const dz = e.group.position.z - this.playerPos.z;
      if (dx * dx + dz * dz > 60 * 60) continue;
      const [x, y] = toMap(e.group.position.x, e.group.position.z);
      ctx.fillStyle = '#ff4a38';
      ctx.beginPath(); ctx.arc(x, y, 2.4, 0, Math.PI * 2); ctx.fill();
      ctx.strokeStyle = 'rgba(255,74,56,0.3)';
      ctx.lineWidth = 4;
      ctx.beginPath(); ctx.arc(x, y, 5, 0, Math.PI * 2); ctx.stroke();
    }

    // player arrow
    const [px, py] = toMap(this.playerPos.x, this.playerPos.z);
    ctx.save();
    ctx.translate(px, py);
    ctx.rotate(-this.playerYaw);
    ctx.fillStyle = '#ffd27a';
    ctx.beginPath();
    ctx.moveTo(0, -8);
    ctx.lineTo(5.5, 6);
    ctx.lineTo(0, 3);
    ctx.lineTo(-5.5, 6);
    ctx.closePath();
    ctx.fill();
    ctx.strokeStyle = 'rgba(0,0,0,0.5)'; ctx.lineWidth = 1; ctx.stroke();
    ctx.restore();

    // view cone
    ctx.save();
    ctx.translate(px, py);
    ctx.rotate(-this.playerYaw);
    const grad = ctx.createLinearGradient(0, 0, 0, -46);
    grad.addColorStop(0, 'rgba(255,210,120,0.22)');
    grad.addColorStop(1, 'rgba(255,210,120,0)');
    ctx.fillStyle = grad;
    ctx.beginPath(); ctx.moveTo(0, 0); ctx.arc(0, 0, 46, -Math.PI / 2 - 0.5, -Math.PI / 2 + 0.5); ctx.closePath(); ctx.fill();
    ctx.restore();

    ctx.restore();
  }
}

import * as THREE from 'three';
import { EffectComposer } from 'three/addons/postprocessing/EffectComposer.js';
import { RenderPass } from 'three/addons/postprocessing/RenderPass.js';
import { UnrealBloomPass } from 'three/addons/postprocessing/UnrealBloomPass.js';
import { OutputPass } from 'three/addons/postprocessing/OutputPass.js';
import { createWorld } from './world.js';
import { Player } from './player.js';
import { EnemyManager } from './enemies.js';
import { Effects } from './effects.js';
import { AudioEngine } from './audio.js';
import { HUD } from './hud.js';
import { clamp, damp, lerp } from './utils.js';

const canvas = document.getElementById('game');
const landing = document.getElementById('landing');
const pauseScreen = document.getElementById('pause');
const resultScreen = document.getElementById('result');
const loadingScreen = document.getElementById('loading');
const loadBar = document.getElementById('loadBar');
const loadStatus = document.getElementById('loadStatus');

const settings = loadSettings();
const state = {
  mode: 'landing',
  time: 0,
  startedAt: 0,
  ended: false,
  locked: false,
  resultTimer: 0
};

const input = {
  forward: false, back: false, left: false, right: false,
  sprint: false, jump: false, crouch: false, fire: false, aim: false,
  reloadJust: false, swapJust: false, weapon1Just: false, weapon2Just: false, interactJust: false
};

/* ───────────────────────── renderer ───────────────────────── */
let renderer;
try {
  renderer = new THREE.WebGLRenderer({ canvas, antialias: true, powerPreference: 'high-performance', alpha: false });
} catch (err) {
  loadStatus.textContent = 'WEBGL INDISPONÍVEL NESTE NAVEGADOR';
  throw err;
}
renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, settings.quality === 'high' ? 1.75 : settings.quality === 'medium' ? 1.35 : 1));
renderer.setSize(window.innerWidth, window.innerHeight);
renderer.outputColorSpace = THREE.SRGBColorSpace;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.06;
renderer.shadowMap.enabled = settings.quality !== 'low';
renderer.shadowMap.type = THREE.PCFSoftShadowMap;

const scene = new THREE.Scene();
const camera = new THREE.PerspectiveCamera(55, window.innerWidth / window.innerHeight, 0.05, 900);
camera.position.set(0, 26, 110);
scene.add(camera);

/* sky environment for metallic weapons */
(function buildEnvironment() {
  const c = document.createElement('canvas');
  c.width = 512; c.height = 256;
  const ctx = c.getContext('2d');
  const g = ctx.createLinearGradient(0, 0, 0, 256);
  g.addColorStop(0, '#6f9fc4');
  g.addColorStop(0.35, '#cad9d6');
  g.addColorStop(0.5, '#ffe1b8');
  g.addColorStop(0.58, '#b49a76');
  g.addColorStop(1, '#3a3a2e');
  ctx.fillStyle = g; ctx.fillRect(0, 0, 512, 256);
  const sun = ctx.createRadialGradient(150, 105, 0, 150, 105, 60);
  sun.addColorStop(0, 'rgba(255,246,214,1)');
  sun.addColorStop(0.25, 'rgba(255,210,140,0.7)');
  sun.addColorStop(1, 'rgba(255,190,110,0)');
  ctx.fillStyle = sun; ctx.fillRect(0, 0, 512, 256);
  const tex = new THREE.CanvasTexture(c);
  tex.mapping = THREE.EquirectangularReflectionMapping;
  tex.colorSpace = THREE.SRGBColorSpace;
  const pmrem = new THREE.PMREMGenerator(renderer);
  scene.environment = pmrem.fromEquirectangular(tex).texture;
  scene.environmentIntensity = 0.55;
  tex.dispose();
  pmrem.dispose();
})();

/* ───────────────────────── world & systems ───────────────────────── */
const world = createWorld(scene, renderer, settings.quality);
const effects = new Effects(scene);
const audio = new AudioEngine();
const hud = new HUD(world, camera);
const player = new Player(scene, camera, world, audio, effects, hud);
const enemies = new EnemyManager(scene, world, effects, audio);
player.enemyManager = enemies;
player.viewRoot.visible = false;

/* ───────────────────────── post processing ───────────────────────── */
const composer = new EffectComposer(renderer);
composer.setPixelRatio(renderer.getPixelRatio());
composer.setSize(window.innerWidth, window.innerHeight);
composer.addPass(new RenderPass(scene, camera));
const bloom = new UnrealBloomPass(new THREE.Vector2(window.innerWidth, window.innerHeight), 0.44, 0.62, 0.86);
bloom.enabled = settings.quality !== 'low';
composer.addPass(bloom);
composer.addPass(new OutputPass());

/* ───────────────────────── zone ───────────────────────── */
const zone = {
  center: new THREE.Vector3(0, 0, 0),
  radius: 136,
  nextRadius: 94,
  targetRadius: 94,
  targetCenter: new THREE.Vector3(0, 0, 0),
  startRadius: 136,
  startCenter: new THREE.Vector3(0, 0, 0),
  phase: 0,
  timer: 58,
  wait: 58,
  shrinkDuration: 34,
  shrinking: false,
  damage: 3.2,
  elapsed: 0
};
const zonePhases = [
  { radius: 94, wait: 42, shrink: 32, damage: 3.5 },
  { radius: 58, wait: 34, shrink: 28, damage: 4.5 },
  { radius: 32, wait: 28, shrink: 24, damage: 6 },
  { radius: 14, wait: 24, shrink: 20, damage: 8 },
  { radius: 6, wait: 9999, shrink: 1, damage: 12 }
];

// visual wall
const wallUniforms = {
  uTime: { value: 0 },
  uColor: { value: new THREE.Color(0xff8b2a) },
  uColor2: { value: new THREE.Color(0x54d7ff) }
};
const wallMat = new THREE.ShaderMaterial({
  transparent: true, depthWrite: false, side: THREE.DoubleSide,
  blending: THREE.AdditiveBlending,
  uniforms: wallUniforms,
  vertexShader: /* glsl */`
    varying vec2 vUv;
    varying vec3 vWorld;
    void main(){
      vUv = uv;
      vec4 wp = modelMatrix * vec4(position,1.0);
      vWorld = wp.xyz;
      gl_Position = projectionMatrix * viewMatrix * wp;
    }`,
  fragmentShader: /* glsl */`
    uniform float uTime;
    uniform vec3 uColor, uColor2;
    varying vec2 vUv;
    varying vec3 vWorld;
    void main(){
      float edge = smoothstep(0.0, 0.16, vUv.y) * smoothstep(1.0, 0.62, vUv.y);
      float grid = abs(sin(vUv.x * 220.0)) * abs(sin(vUv.y * 34.0 - uTime * 0.6));
      float lines = smoothstep(0.82, 0.98, grid);
      float pulse = 0.55 + 0.45 * sin(uTime * 2.0 + vUv.x * 12.0);
      vec3 col = mix(uColor2, uColor, 0.35 + 0.4 * sin(vUv.x * 6.28 + uTime * 0.4));
      float a = (0.045 + lines * 0.22 + pulse * 0.03) * edge;
      gl_FragColor = vec4(col * (0.7 + lines * 1.8), a);
    }`
});
const wall = new THREE.Mesh(new THREE.CylinderGeometry(1, 1, 150, 128, 1, true), wallMat);
wall.position.set(0, 55, 0);
wall.frustumCulled = false;
scene.add(wall);
const zoneRing = new THREE.Mesh(
  new THREE.RingGeometry(0.985, 1.015, 128),
  new THREE.MeshBasicMaterial({ color: 0xffb25a, transparent: true, opacity: 0.55, side: THREE.DoubleSide, depthWrite: false })
);
zoneRing.rotation.x = -Math.PI / 2;
zoneRing.position.y = 1.6;
zoneRing.scale.setScalar(zone.radius);
scene.add(zoneRing);

/* ───────────────────────── match flow ───────────────────────── */
function resetMatch() {
  player.reset();
  player.enabled = true;
  player.viewRoot.visible = true;
  enemies.reset();
  enemies.spawn(11, player);
  enemies.onKill = onEnemyKilled;
  player.onKill = onEnemyKilled;
  player.onDeath = () => { if (!state.ended) endMatch(false); };
  state.ended = false;
  state.resultTimer = 0;
  state.startedAt = performance.now();
  hud.setKills(0);
  hud.setAlive(12);
  hud.setZone(zone);
  hud.setEnemies(enemies.enemies);
  hud.el.killfeed.innerHTML = '';
  zone.center.set(0, 0, 0);
  zone.radius = 136;
  zone.nextRadius = 94;
  zone.targetRadius = 94;
  zone.phase = 0;
  zone.timer = 58;
  zone.wait = 58;
  zone.shrinkDuration = 34;
  zone.shrinking = false;
  zone.damage = 3.2;
  zone.elapsed = 0;
  wall.scale.set(136, 1, 136);
  zoneRing.scale.setScalar(136);
  hud.zoneWarning(false);
  hud.toast('PARTIDA INICIADA', 'ENCONTRE ARMAS · SOBREVIVA');
}

function startMatch() {
  audio.init();
  audio.resume();
  audio.setEnabled(settings.sound);
  landing.hidden = true;
  resultScreen.hidden = true;
  pauseScreen.hidden = true;
  hud.show();
  state.mode = 'playing';
  state.startedAt = performance.now();
  resetMatch();
  requestLock();
  setTimeout(() => {
    if (state.mode === 'playing' && !state.locked) hud.lockHint(true);
  }, 900);
  setTimeout(() => hud.lockHint(false), 5200);
}

function requestLock() {
  try {
    const p = canvas.requestPointerLock?.({ unadjustedMovement: false });
    if (p && p.catch) p.catch(() => {});
  } catch {
    hud.lockHint(true);
  }
}

function pauseMatch() {
  if (state.mode !== 'playing') return;
  state.mode = 'paused';
  pauseScreen.hidden = false;
  document.getElementById('pauseKills').textContent = player.stats.kills;
  document.getElementById('pauseAcc').textContent = accuracy();
  document.getElementById('pauseTime').textContent = matchTime();
  clearInput();
}

function resumeMatch() {
  pauseScreen.hidden = true;
  state.mode = 'playing';
  requestLock();
}

function quitToMenu() {
  state.mode = 'landing';
  pauseScreen.hidden = true;
  resultScreen.hidden = true;
  hud.hide();
  player.enabled = false;
  player.viewRoot.visible = false;
  document.exitPointerLock?.();
  clearInput();
  landing.hidden = false;
}

function endMatch(win) {
  if (state.ended) return;
  state.ended = true;
  state.resultTimer = 0.9;
  state.win = win;
  clearInput();
  if (win) audio.victory(); else audio.defeat();
  document.exitPointerLock?.();
}

function showResult() {
  state.mode = 'result';
  hud.hide();
  document.exitPointerLock?.();
  const card = resultScreen.querySelector('.result-card');
  card.classList.toggle('lose', !state.win);
  document.getElementById('resultEyebrow').innerHTML = state.win
    ? '<span></span> VITÓRIA · ILHA ZERO'
    : '<span></span> FIM DE PARTIDA';
  document.getElementById('resultTitle').textContent = state.win ? 'BOOYAH!' : 'ELIMINADO';
  document.getElementById('resultSub').textContent = state.win
    ? 'Você dominou a Ilha Zero. O último de pé leva tudo.'
    : `Você caiu em combate. ${enemies.alive + 1}º lugar de 12 operadores.`;
  document.getElementById('resKills').textContent = player.stats.kills;
  document.getElementById('resPlace').textContent = state.win ? '#1' : `#${enemies.alive + 1}`;
  document.getElementById('resAcc').textContent = accuracy();
  document.getElementById('resTime').textContent = matchTime();
  document.getElementById('resultQuote').textContent = state.win
    ? '“O fogo não escolhe. Ele consome.”'
    : '“A ilha não perdoa. Ela só cobra.”';
  resultScreen.hidden = false;
}

function accuracy() {
  if (!player.stats.shots) return '0%';
  return `${Math.round((player.stats.hits / player.stats.shots) * 100)}%`;
}
function matchTime() {
  const sec = Math.floor((performance.now() - state.startedAt) / 1000);
  return `${String(Math.floor(sec / 60)).padStart(2, '0')}:${String(sec % 60).padStart(2, '0')}`;
}

function onEnemyKilled(enemy) {
  if (!enemy || enemy.counted) return;
  enemy.counted = true;
  hud.setKills(player.stats.kills);
  hud.killfeed('VOCÊ', enemy.name, 'FÚRIA', false, true);
  hud.setAlive(Math.max(1, enemies.alive + 1));
  if (enemies.alive === 0 && !state.ended) {
    setTimeout(() => { if (!state.ended) endMatch(true); }, 700);
  }
}

function clearInput() {
  for (const k of Object.keys(input)) input[k] = typeof input[k] === 'boolean' ? false : input[k];
}

/* ───────────────────────── zone update ───────────────────────── */
function updateZone(dt) {
  zone.elapsed += dt;
  if (zone.shrinking) {
    zone.timer -= dt;
    const total = zone.shrinkDuration;
    const t = 1 - clamp(zone.timer / total, 0, 1);
    const e = t * t * (3 - 2 * t);
    zone.radius = lerp(zone.startRadius, zone.targetRadius, e);
    zone.center.lerpVectors(zone.startCenter, zone.targetCenter, e);
    if (zone.timer <= 0) {
      zone.radius = zone.targetRadius;
      zone.center.copy(zone.targetCenter);
      zone.shrinking = false;
      zone.phase++;
      const phase = zonePhases[Math.min(zone.phase, zonePhases.length - 1)];
      zone.timer = phase.wait;
      zone.wait = phase.wait;
      zone.shrinkDuration = phase.shrink;
      zone.nextRadius = phase.radius;
      zone.damage = phase.damage;
      if (phase.radius < zone.radius - 1) {
        chooseNextCenter(phase.radius);
        audio.zone();
        hud.toast('ZONA FECHANDO', `PRÓXIMO RAIO ${Math.round(phase.radius)} m`);
      }
    }
  } else {
    zone.timer -= dt;
    if (zone.timer <= 0 && zone.phase < zonePhases.length) {
      const phase = zonePhases[zone.phase];
      zone.targetRadius = phase.radius;
      zone.shrinkDuration = phase.shrink;
      zone.timer = phase.shrink;
      zone.shrinking = true;
      zone.startRadius = zone.radius;
      zone.startCenter.copy(zone.center);
      chooseNextCenter(phase.radius);
      audio.zone();
      hud.toast('ZONA FECHANDO', 'MOVA-SE PARA O CÍRCULO');
    }
  }
  wall.position.set(zone.center.x, 55, zone.center.z);
  wall.scale.set(zone.radius, 1, zone.radius);
  zoneRing.position.set(zone.center.x, 1.8, zone.center.z);
  zoneRing.scale.setScalar(zone.radius);
  wallUniforms.uTime.value = state.time;
  hud.setZone(zone);
  hud.setZoneUi(zone.timer, zone.shrinking);

  const d = Math.hypot(player.position.x - zone.center.x, player.position.z - zone.center.z);
  const outside = d > zone.radius;
  hud.zoneWarning(outside && player.alive);
  if (outside && player.alive) player.zoneDamage(zone.damage * dt);
  // bots take zone damage too
  for (const e of enemies.enemies) {
    if (e.dead) continue;
    const ed = Math.hypot(e.group.position.x - zone.center.x, e.group.position.z - zone.center.z);
    if (ed > zone.radius) {
      e.hp -= zone.damage * 0.7 * dt;
      if (e.hp <= 0) {
        e.die();
        hud.killfeed('ZONA', e.name, 'ZONA');
        hud.setAlive(Math.max(1, enemies.alive + 1));
      }
    }
  }
}

function chooseNextCenter(radius) {
  const rng = Math.random;
  const maxOffset = Math.max(0, zone.radius - radius) * 0.55;
  const a = rng() * Math.PI * 2;
  const r = Math.sqrt(rng()) * maxOffset;
  zone.targetCenter.set(zone.center.x + Math.cos(a) * r, 0, zone.center.z + Math.sin(a) * r);
  // keep inside the island
  const len = Math.hypot(zone.targetCenter.x, zone.targetCenter.z);
  if (len > 105) zone.targetCenter.multiplyScalar(105 / len);
}

/* ───────────────────────── landing camera ───────────────────────── */
function updateLandingCamera(t) {
  const a = 0.18 + Math.sin(t * 0.045) * 0.16;
  const r = 128 + Math.sin(t * 0.06) * 6;
  const x = Math.sin(a) * r;
  const z = Math.cos(a) * r;
  const y = 34 + Math.sin(t * 0.08) * 4;
  camera.position.set(x, y, z);
  camera.lookAt(0, 9, -12);
  camera.fov = 58;
  camera.updateProjectionMatrix();
  player.viewRoot.visible = false;
}

/* ───────────────────────── events ───────────────────────── */
document.getElementById('playBtn').addEventListener('click', startMatch);
document.getElementById('againBtn').addEventListener('click', startMatch);
document.getElementById('resumeBtn').addEventListener('click', resumeMatch);
document.getElementById('quitBtn').addEventListener('click', quitToMenu);
document.getElementById('menuBtn').addEventListener('click', quitToMenu);

document.getElementById('settingsBtn').addEventListener('click', () => {
  document.getElementById('helpPanel').hidden = true;
  document.getElementById('settingsPanel').hidden = !document.getElementById('settingsPanel').hidden;
  syncSettingsUi();
});
document.getElementById('helpBtn').addEventListener('click', () => {
  document.getElementById('settingsPanel').hidden = true;
  document.getElementById('helpPanel').hidden = !document.getElementById('helpPanel').hidden;
});
document.querySelectorAll('.panel-close').forEach(btn => {
  btn.addEventListener('click', () => { document.getElementById(btn.dataset.close).hidden = true; });
});
document.getElementById('sensRange').addEventListener('input', (e) => {
  settings.sensitivity = parseFloat(e.target.value);
  document.getElementById('sensVal').textContent = settings.sensitivity.toFixed(1);
  player.sensitivity = settings.sensitivity;
  saveSettings();
});
document.getElementById('qualitySelect').addEventListener('change', (e) => {
  settings.quality = e.target.value;
  applyQuality();
  saveSettings();
});
document.getElementById('soundToggle').addEventListener('change', (e) => {
  settings.sound = e.target.checked;
  audio.setEnabled(settings.sound);
  saveSettings();
});
document.getElementById('adsToggle').addEventListener('change', (e) => {
  settings.ads = e.target.checked;
  saveSettings();
});

function syncSettingsUi() {
  document.getElementById('sensRange').value = settings.sensitivity;
  document.getElementById('sensVal').textContent = Number(settings.sensitivity).toFixed(1);
  document.getElementById('qualitySelect').value = settings.quality;
  document.getElementById('soundToggle').checked = settings.sound;
  document.getElementById('adsToggle').checked = settings.ads;
}

function applyQuality() {
  const pr = Math.min(window.devicePixelRatio || 1, settings.quality === 'high' ? 1.75 : settings.quality === 'medium' ? 1.35 : 1);
  renderer.setPixelRatio(pr);
  composer.setPixelRatio(pr);
  bloom.enabled = settings.quality !== 'low';
  renderer.shadowMap.enabled = settings.quality !== 'low';
  world.sun.castShadow = settings.quality !== 'low';
  resize();
}

document.addEventListener('pointerlockchange', () => {
  state.locked = document.pointerLockElement === canvas;
  if (state.locked) {
    hud.lockHint(false);
  } else if (state.mode === 'playing' && !state.ended) {
    setTimeout(() => {
      if (!state.locked && state.mode === 'playing') pauseMatch();
    }, 180);
  }
});
document.addEventListener('pointerlockerror', () => {
  hud.lockHint(true);
  setTimeout(() => hud.lockHint(false), 4000);
});

canvas.addEventListener('click', () => {
  if (state.mode === 'playing' && !state.locked && !state.ended) requestLock();
});

window.addEventListener('keydown', (e) => {
  if (state.mode === 'landing') {
    if (e.code === 'Enter' || e.code === 'Space') { e.preventDefault(); startMatch(); }
    return;
  }
  if (state.mode === 'paused') {
    if (e.code === 'Escape' || e.code === 'Enter') { e.preventDefault(); resumeMatch(); }
    return;
  }
  if (state.mode !== 'playing') return;
  switch (e.code) {
    case 'KeyW': case 'ArrowUp': input.forward = true; break;
    case 'KeyS': case 'ArrowDown': input.back = true; break;
    case 'KeyA': case 'ArrowLeft': input.left = true; break;
    case 'KeyD': case 'ArrowRight': input.right = true; break;
    case 'ShiftLeft': case 'ShiftRight': input.sprint = true; break;
    case 'Space': input.jump = true; e.preventDefault(); break;
    case 'ControlLeft': case 'KeyC': input.crouch = true; break;
    case 'KeyR': input.reloadJust = true; break;
    case 'KeyQ': input.swapJust = true; break;
    case 'Digit1': input.weapon1Just = true; break;
    case 'Digit2': input.weapon2Just = true; break;
    case 'KeyE': input.interactJust = true; break;
    case 'Escape': pauseMatch(); break;
  }
});
window.addEventListener('keyup', (e) => {
  switch (e.code) {
    case 'KeyW': case 'ArrowUp': input.forward = false; break;
    case 'KeyS': case 'ArrowDown': input.back = false; break;
    case 'KeyA': case 'ArrowLeft': input.left = false; break;
    case 'KeyD': case 'ArrowRight': input.right = false; break;
    case 'ShiftLeft': case 'ShiftRight': input.sprint = false; break;
    case 'ControlLeft': case 'KeyC': input.crouch = false; break;
  }
});

document.addEventListener('mousemove', (e) => {
  if (state.mode !== 'playing' || !state.locked || !player.alive) return;
  player.look(e.movementX || 0, e.movementY || 0, settings.sensitivity);
});
canvas.addEventListener('mousedown', (e) => {
  if (state.mode !== 'playing') return;
  if (e.button === 0) input.fire = true;
  if (e.button === 2 && settings.ads) input.aim = true;
  if (!state.locked) requestLock();
});
window.addEventListener('mouseup', (e) => {
  if (e.button === 0) input.fire = false;
  if (e.button === 2) input.aim = false;
});
window.addEventListener('contextmenu', (e) => e.preventDefault());
window.addEventListener('blur', () => {
  clearInput();
  if (state.mode === 'playing') pauseMatch();
});

function resize() {
  const w = window.innerWidth, h = window.innerHeight;
  camera.aspect = w / h;
  camera.updateProjectionMatrix();
  renderer.setSize(w, h);
  composer.setSize(w, h);
}
window.addEventListener('resize', resize);

/* ───────────────────────── loading ───────────────────────── */
let loadProgress = 0;
const loadTimer = setInterval(() => {
  loadProgress = Math.min(0.92, loadProgress + 0.12 + Math.random() * 0.1);
  loadBar.style.width = `${Math.round(loadProgress * 100)}%`;
  if (loadProgress > 0.5) loadStatus.textContent = 'POSICIONANDO OPERADORES…';
}, 120);
setTimeout(() => {
  clearInterval(loadTimer);
  loadBar.style.width = '100%';
  loadStatus.textContent = 'PRONTO PARA O COMBATE';
  setTimeout(() => loadingScreen.classList.add('done'), 280);
}, 900);

/* ───────────────────────── main loop ───────────────────────── */
const clock = new THREE.Clock();
state.time = 0;

function frame() {
  requestAnimationFrame(frame);
  const dt = Math.min(clock.getDelta(), 0.05);
  state.time += dt;
  const t = state.time;

  world.update(dt, t);
  effects.update(dt);
  wallUniforms.uTime.value = t;

  if (state.mode === 'landing') {
    updateLandingCamera(t);
    hud.setAlive(12);
  } else if (state.mode === 'playing') {
    player.update(dt, input, t);
    enemies.update(dt, player, t);
    updateZone(dt);
    hud.setEnemies(enemies.enemies);
    hud.setAlive(Math.max(1, enemies.alive + 1));
    hud.update(t, dt);
    if (state.ended) {
      state.resultTimer -= dt;
      if (state.resultTimer <= 0 && state.mode === 'playing') showResult();
    }
    player.viewRoot.visible = player.alive;
    if (!player.alive) {
      // death cam drift
      player.camera.position.y = damp(player.camera.position.y, player.position.y + 1.2, 3, dt);
    }
  } else if (state.mode === 'paused') {
    hud.update(t, dt);
  } else if (state.mode === 'result') {
    // keep ambient animation alive behind overlay
  }

  // debug readout
  const fps = Math.round(1 / Math.max(dt, 0.0001));
  hud.el.debug.textContent = `${settings.quality.toUpperCase()} · ${fps} FPS`;

  composer.render();
}

frame();

