import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 });
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
page.on('pageerror', e => console.log('ERR', e.message));
await page.goto('http://localhost:3002/', { waitUntil: 'load' });
await page.waitForTimeout(1600);
const url = '/tmp/ff-check/';
await page.screenshot({ path: url + 'd2-base.png' });
await page.evaluate(() => { document.getElementById('grain').style.display = 'none'; });
await page.waitForTimeout(200);
await page.screenshot({ path: url + 'd2-nograin.png' });
// hide loot groups
await page.evaluate(() => { const p = window.__ff.player; p.pickups?.forEach(g => g.visible = false); });
await page.waitForTimeout(200);
await page.screenshot({ path: url + 'd2-noloot.png' });
// hide all sprites
await page.evaluate(() => { window.__ff.world.scene.traverse(o => { if (o.isSprite) o.visible = false; }); });
await page.waitForTimeout(200);
await page.screenshot({ path: url + 'd2-nosprites.png' });
// hide sky
await page.evaluate(() => { const s = window.__ff.world.scene; s.traverse(o => { if (o.isMesh && o.geometry?.type === 'SphereGeometry') o.visible = false; }); });
await page.waitForTimeout(200);
await page.screenshot({ path: url + 'd2-nosky.png' });
console.log(await page.evaluate(() => {
  const s = window.__ff.world.scene;
  let sprites = 0, points = 0, meshes = 0;
  const spriteInfo = [];
  s.traverse(o => { if (o.isSprite) { sprites++; if (o.visible) spriteInfo.push({ pos: o.position.toArray().map(n => +n.toFixed(1)), scale: o.scale.toArray().map(n => +n.toFixed(1)), op: o.material.opacity }); } if (o.isPoints) points++; if (o.isMesh) meshes++; });
  return { sprites, visibleSprites: spriteInfo, points, meshes, exposure: window.__ff.renderer.toneMappingExposure, cam: window.__ff.camera.position.toArray() };
}));
await browser.close();

