import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 });
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
const b64 = p => 'data:image/png;base64,' + readFileSync('/tmp/ff-check/' + p).toString('base64');
const res = await page.evaluate(async ([a, b]) => {
  const load = src => new Promise(r => { const i = new Image(); i.onload = () => r(i); i.src = src; });
  const [ia, ib] = await Promise.all([load(a), load(b)]);
  const c = document.createElement('canvas'); c.width = ia.width; c.height = ia.height;
  const x = c.getContext('2d', { willReadFrequently: true });
  x.drawImage(ia, 0, 0); const da = x.getImageData(0, 0, c.width, c.height).data;
  x.clearRect(0, 0, c.width, c.height); x.drawImage(ib, 0, 0); const db = x.getImageData(0, 0, c.width, c.height).data;
  const pts = [];
  for (let y = 0; y < c.height; y += 1) for (let xx = 0; xx < c.width; xx += 1) {
    const i = (y * c.width + xx) * 4;
    const d = Math.abs(da[i] - db[i]) + Math.abs(da[i + 1] - db[i + 1]) + Math.abs(da[i + 2] - db[i + 2]);
    if (d > 30) pts.push([xx, y, d]);
  }
  // cluster by grid
  const cells = {};
  for (const [xx, y, d] of pts) { const k = Math.floor(xx / 40) + ',' + Math.floor(y / 40); (cells[k] ||= []).push([xx, y, d]); }
  const top = Object.entries(cells).sort((p, q) => q[1].length - p[1].length).slice(0, 25).map(([k, v]) => ({ cell: k, n: v.length, maxD: Math.max(...v.map(z => z[2])), sample: v[0] }));
  return { total: pts.length, top };
}, [b64('d2-base.png'), b64('d2-noloot.png')]);
console.log(JSON.stringify(res, null, 1));
await browser.close();

import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 });
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
await page.goto('http://localhost:3002/', { waitUntil: 'load' });
await page.waitForTimeout(1400);
// freeze camera and time by stopping the loop? Set player camera manually and render once via composer? Instead screenshot immediately after short wait
await page.screenshot({ path: '/tmp/ff-check/crop-tl.png', clip: { x: 0, y: 60, width: 500, height: 400 } });
// locate bright blobs in sky region
const b = readFileSync('/tmp/ff-check/d2-base.png').toString('base64');
const blobs = await page.evaluate(async (b64) => {
  const img = await new Promise(r => { const i = new Image(); i.onload = () => r(i); i.src = 'data:image/png;base64,' + b64; });
  const c = document.createElement('canvas'); c.width = 700; c.height = 900;
  const x = c.getContext('2d', { willReadFrequently: true });
  x.drawImage(img, 0, 0, 700, 900, 0, 0, 700, 900);
  const d = x.getImageData(0, 0, 700, 900).data;
  const pts = [];
  for (let y = 80; y < 460; y++) for (let xx = 0; xx < 700; xx++) {
    if (xx > 540 && y > 250) continue; // skip title maybe
    const i = (y * 700 + xx) * 4;
    const r = d[i], g = d[i + 1], bl = d[i + 2];
    const lum = r * 0.3 + g * 0.5 + bl * 0.2;
    if (lum > 140) pts.push([xx, y, Math.round(lum), r, g, bl]);
  }
  return pts.slice(0, 200);
}, b);
// group points into blobs crudely
const seen = []; let groups = [];
for (const p of blobs) {
  let g = groups.find(q => Math.hypot(q.cx - p[0], q.cy - p[1]) < 30);
  if (!g) groups.push({ cx: p[0], cy: p[1], n: 1, lum: p[2], rgb: [p[3], p[4], p[5]] });
  else { g.cx = (g.cx * g.n + p[0]) / (g.n + 1); g.cy = (g.cy * g.n + p[1]) / (g.n + 1); g.n++; g.lum = Math.max(g.lum, p[2]); }
}
console.log(groups.filter(g => g.n > 4).slice(0, 30));
await browser.close();

