import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 });
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
page.on('pageerror', e => console.log('ERR', e.message));
await page.goto('http://localhost:3002/', { waitUntil: 'load' });
await page.waitForTimeout(1500);
await page.click('#playBtn');
await page.waitForTimeout(2000);
await page.screenshot({ path: '/tmp/ff-check/g-base.png' });
await page.evaluate(() => { window.__ff.world.scene.traverse(o => { if (o.isSprite && o.scale.x > 50) o.visible = false; }); });
await page.waitForTimeout(300);
await page.screenshot({ path: '/tmp/ff-check/g-noclouds.png' });
// restore, hide only sun (scale 90, additive)
await page.evaluate(() => { window.__ff.world.scene.traverse(o => { if (o.isSprite && o.scale.x > 50) o.visible = true; if (o.isSprite && o.material.blending === 2) o.visible = false; }); });
await page.waitForTimeout(300);
await page.screenshot({ path: '/tmp/ff-check/g-noadditive.png' });
console.log(await page.evaluate(() => {
  const out = {};
  window.__ff.world.scene.traverse(o => {
    if (o.isSprite && o.scale.x > 50) {
      const k = o.scale.x.toFixed(0) + 'x' + o.scale.y.toFixed(0) + (o.material.blending === 2 ? ' add' : ' norm');
      out[k] = (out[k] || 0) + 1;
    }
  });
  return out;
}));
await browser.close();

