process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 });
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
page.on('pageerror', e => console.log('ERR', e.message));
await page.goto('http://localhost:3002/', { waitUntil: 'load' });
await page.waitForTimeout(1500);
await page.click('#playBtn');
await page.waitForTimeout(1800);
const snap = async (name, fn) => { await page.evaluate(fn); await page.waitForTimeout(250); await page.screenshot({ path: '/tmp/ff-check/' + name + '.png' }); };
await snap('h-base', () => {});
await snap('h-nosprites', () => { window.__ff.world.scene.traverse(o => { if (o.isSprite) o.visible = false; }); });
await snap('h-nopoints', () => { window.__ff.world.scene.traverse(o => { if (o.isPoints) o.visible = false; }); });
await snap('h-nosky', () => { window.__ff.world.scene.traverse(o => { if (o.isMesh && o.geometry?.type === 'SphereGeometry') o.visible = false; }); });
await snap('h-nobloom', () => { window.__ff.renderer.info; window.__ff.bloom && (window.__ff.bloom.enabled = false); });
console.log(await page.evaluate(() => ({ keys: Object.keys(window.__ff), bloom: !!window.__ff.bloom })));
await browser.close();

