import { readFileSync } from 'node:fs';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 });
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
await page.goto('http://localhost:3002/', { waitUntil: 'load' });
await page.waitForTimeout(1500);
await page.click('#playBtn');
await page.waitForTimeout(1800);
const snap = async (name, fn) => { await page.evaluate(fn); await page.waitForTimeout(300); await page.screenshot({ path: '/tmp/ff-check/' + name + '.png' }); };
await snap('i-nograin', () => { document.getElementById('grain').style.display = 'none'; });
await snap('i-nocanvas', () => { document.getElementById('game').style.visibility = 'hidden'; });
await snap('i-nocanvas-nograin', () => { document.getElementById('grain').style.display = 'none'; });
console.log(await page.evaluate(() => {
  const els = [...document.querySelectorAll('body *')].map(e => ({ tag: e.tagName, id: e.id, cls: e.className, z: getComputedStyle(e).zIndex, bg: getComputedStyle(e).backgroundImage.slice(0, 40) })).filter(e => e.bg && e.bg !== 'none');
  return els;
}));
await browser.close();

