import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 });
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
await page.goto('http://localhost:3002/', { waitUntil: 'load' });
await page.waitForTimeout(1500);
await page.click('#playBtn');
await page.waitForTimeout(1800);
await page.evaluate(() => { document.getElementById('grain').style.display = 'none'; });
await page.screenshot({ path: '/tmp/ff-check/k-p0.png' });
await page.evaluate(() => { window.__ff.player.pitch = 0.45; });
await page.waitForTimeout(400);
await page.screenshot({ path: '/tmp/ff-check/k-p1.png' });
await page.evaluate(() => { window.__ff.player.yaw += 1.2; });
await page.waitForTimeout(400);
await page.screenshot({ path: '/tmp/ff-check/k-yaw.png' });
// categorise objects
console.log(await page.evaluate(() => {
  const g = { sprites: 0, points: 0, inst: 0, mesh: 0, lines: 0 };
  const mats = {};
  window.__ff.world.scene.traverse(o => {
    if (o.isSprite) g.sprites++;
    else if (o.isPoints) g.points++;
    else if (o.isInstancedMesh) g.inst++;
    else if (o.isLine) g.lines++;
    else if (o.isMesh) { g.mesh++; const k = o.geometry.type + ':' + (o.material.type) + ':' + (o.material.transparent ? 'T' : 'O'); mats[k] = (mats[k] || 0) + 1; }
  });
  return { g, mats: Object.entries(mats).sort((a, b) => b[1] - a[1]).slice(0, 20) };
}));
await browser.close();

